    ' Перенос отменён.' => '转移已取消。',
    'Не удалось полностью отменить перенос. Проверьте обе папки.' => '无法完全取消转移。检查两个文件夹。',
    'Выберите папки контента. Служебные каталоги недоступны.' => '选择内容文件夹。服务目录不可用。',
    'Выберите папку вне переносимого раздела.' => '选择要移动的分区外部的文件夹。',
    'Папка изменилась или отсутствует в дереве страниц.' => '该文件夹已更改或从页面树中丢失。',
    'В папке назначения уже есть такой файл или каталог.' => '目标文件夹中已存在这样的文件或目录。',
    'После переноса адрес одной из страниц станет слишком длинным.' => '传输后，其中一页的地址会变得太长。',
    'Одна из страниц изменилась. Обновите список.' => '其中一页已更改。更新列表。',
    'Не удалось переместить каталог. Проверьте права записи.' => '移动目录失败。检查写入权限。',
    'Перенос отменён. Проверьте права записи внутри папки.' => '转移已取消。检查文件夹内的写入权限。',
    'Не удалось полностью отменить перенос. Проверьте исходную папку и папку назначения.' => '无法完全取消转移。检查源文件夹和目标文件夹。',
    'Список страниц изменился. Обновите его перед сортировкой.' => '页面列表已更改。在排序之前更新它。',
