    'Создать учётную запись' => '创建一个帐户',
    'Одноразовый код установки' => '一次性安装代码',
    'Логин' => '登录',
    'Пароль' => '密码',
    'От 8 символов, не более 72 байт.' => '8 个字符起，不超过 72 个字节。',
    'Повторите пароль' => '重复密码',
    'Создать учётную запись и продолжить' => '创建帐户并继续',
    'В каталоге сайта выполните' => '在站点目录中，运行',
    ', затем обновите страницу и введите полученный код.' => '，然后刷新页面并输入您收到的代码。',
    'Вход в админку' => '登录管理面板',
    'Войти' => '登录',
    'Завершить первичную настройку сайта' => '完成初始站点设置',
    'Папки и страницы' => '文件夹和页面',
    'Скрыть страницу' => '隐藏页面',
    'Опубликовать страницу' => '发布页面',
    'Удалить страницу' => '删除页面',
    'Файл страницы будет удалён. Остальные файлы в её папке останутся.' => '页面文件将被删除。她的文件夹中的剩余文件将保留。',
    'Страница исчезнет из меню и будет недоступна по прямой ссылке, пока вы её не опубликуете.' => '该页面将从菜单中消失，并且在您发布之前无法通过直接链接访问。',
    'Новая страница' => '新页面',
    'Редактирование страницы' => '编辑页面',
    'Выберите папку' => '选择文件夹',
    'Адрес страницы' => '页面地址',
    'В именах файлов и папок разрешены A–Z, a–z, 0–9, дефис (-) и подчёркивание (_). Без пробелов. Примеры: /Services-1/ и /Services-1/About_2.php.' => '文件和文件夹名称中允许使用 A–Z、a–z、0–9、连字符 (-) 和下划线 (_)。没有空格。示例：/Services-1/ 和 /Services-1/About_2.php。',
    'Название в меню' => '菜单名称',
    'Порядок в меню' => '菜单顺序',
    'Если поле пустое, в меню используется заголовок вкладки.' => '如果该字段为空，则菜单使用选项卡标题。',
    'CSS и JavaScript страницы' => 'CSS 和 JavaScript 页面',
    'Заголовок вкладки' => '选项卡标题',
    'Заголовок H1' => '标题 H1',
    'Метаописание' => '元描述',
    'Выбрать на карте' => '在地图上选择',
    'Нажмите в нужном месте или перетащите метку.' => '单击所需位置或拖动标记。',
    'Не удалось загрузить карту. Проверьте ключ, ограничения домена и соединение.' => '加载地图失败。检查密钥、域限制和连接。',
    'Переводы страницы' => '页面翻译',
    'Нужен другой язык?' => '需要其他语言？',
    'Добавить язык сайта' => '添加网站语言',
    'Показать' => '展示',
    'Скрыть' => '隐藏',
    'Переместить страницу' => '移动页面',
    'Папка назначения' => '目标文件夹',
    'В именах папок разрешены A–Z, a–z, 0–9, дефис (-) и подчёркивание (_). Без пробелов. Можно указать новую папку. Подпапки страницы останутся по прежним адресам.' => '文件夹名称中允许使用 A-Z、a-z、0-9、连字符 (-) 和下划线 (_)。没有空格。您可以指定一个新文件夹。页面的子文件夹将保留在相同的地址。',
    'Переместить' => '移动',
    'Версия' => '版本',
    'Установка и вход' => '安装与登录',
    'Как запустить сайт и открыть админку?' => '如何启动网站并打开管理面板？',
    'Для локального запуска выполните в каталоге проекта команду php -S 127.0.0.1:8000 router.php и откройте http://127.0.0.1:8000/admin/. На хостинге сначала выполните php admin/setup.php, затем введите полученный одноразовый код на первом шаге мастера в /admin/.' => '要本地启动，请在项目目录中运行命令 php -S 127.0.0.1:8000 router.php 并打开 http://127.0.0.1:8000/admin/. 在主机上，首先运行 php admin/setup.php，然后在 /admin/. 中输入向导第一步中收到的一次性代码',
    'Что можно настроить при первом запуске?' => '第一次启动时可以配置什么？',
    'Сначала создайте логин и пароль. На втором шаге задайте название сайта, метаописание по умолчанию, текст подвала, палитру и режим темы. При наличии PHP GD можно сразу загрузить логотип и создать из него favicon. Второй шаг можно пропустить или продолжить при следующем входе.' => '首先创建用户名和密码。第二步，设置站点名称、默认元描述、页脚文本、调色板和主题模式。如果您有 PHP GD，您可以立即下载徽标并从中创建网站图标。您可以跳过第二步或下次登录时继续。',
    'Страницы и меню' => '页面和菜单',
    'Как создать страницу и какой адрес указать?' => '如何创建页面以及输入什么地址？',
    'Откройте «Страницы → Новая страница». Укажите адрес, например /Services-1/Repair/ или /Services-1/Price_2.php, заполните заголовок и сохраните. Для адреса папки движок сам создаст каталоги и index.php. В именах разрешены A–Z, a–z, 0–9, дефис и подчёркивание. В корне зарезервирована главная страница, а создание страниц в служебных каталогах закрыто.' => '转到页面 → 新页面。输入地址，例如/Services-1/Repair/或/Services-1/Price_2.php，填写标题并保存。对于文件夹地址，引擎本身会创建目录和index.php。名称中允许使用 A-Z、a-z、0-9、连字符和下划线。主页面保留在根目录下，服务目录下的页面创建是关闭的。',
    'Чем отличается галочка «В меню» от кнопки «Скрыть»?' => '“在菜单中”复选框和“隐藏”按钮有什么区别？',
    'Снятие галочки «В меню» убирает ссылку из штатных меню, сохраняя доступ по прямому адресу. У страницы с адресом папки галочка также управляет пунктами вложенных страниц. Кнопка «Скрыть» убирает ссылку и закрывает публичный адрес страницы до повторной публикации.' => '取消选中“在菜单中”框将从常规菜单中删除链接，同时保留对直接地址的访问。在具有文件夹地址的页面上，该复选框还控制子页面上的项目。 “隐藏”按钮会删除链接并关闭页面的公共地址，直到再次发布。',
    'Как изменить порядок страниц или перенести целую папку?' => '如何更改页面顺序或移动整个文件夹？',
    'Почему изменения страницы сразу не видны?' => '为什么页面更改不能立即可见？',
    'Нажмите «Сохранить» в редакторе. Затем воспользуйтесь ссылкой «Открыть страницу» или «Перейти». Если ссылка исчезла, проверьте, опубликована ли страница. Для изменений на поддомене сверяйте домен в адресной строке.' => '在编辑器中单击“保存”。然后使用“打开页面”或“前往”链接。如果链接消失，请检查页面是否已发布。对于子域的更改，请检查地址栏中的域。',
    'Оформление и поддомены' => '设计和子域',
    'Где поменять название, подвал, логотип и favicon?' => '在哪里可以更改标题、页脚、徽标和图标？',
    'Откройте «Настройки → Основные». Поле «Текст подвала» поддерживает [year] для текущего года. В блоке «Логотипы и иконки сайта» можно загрузить изображения или нажать «Создать favicon из логотипа». Загрузка и преобразование требуют PHP GD.' => '打开设置 → 常规。页脚文本字段支持当前年份的 [year]。在“徽标和站点图标”块中，您可以上传图像或单击“从徽标创建网站图标”。加载和转换需要PHP GD。',
    'Как сменить тему или шрифт и потом вернуть прежний?' => '如何更改主题或字体然后返回到旧的？',
    'В «Шаблоны оформления → Темы дизайна» включается готовый сайт. Цвета и шрифты открываются отдельными вкладками. Можно включить несколько семейств и сохранить их локально.' => '在“设计模板 → 设计主题”中启用完整站点。站点颜色和字体有各自的选项卡，可启用多个字体并保存本地副本。',
    'Где менять шапку и куда вставить счётчик, CSS или JavaScript?' => '在哪里更改标题以及在哪里插入计数器、CSS 或 JavaScript？',
    'Общие блоки header, mobile-menu, menu и footer редактируются во вкладке «Шаблоны оформления». Там же «Служебные заголовки» вставляют HTML в head или перед закрывающим тегом body. Для обычных CSS и JavaScript есть отдельная вкладка «CSS и JS». Код одной страницы добавляется в её редакторе.' => '公共块标题、移动菜单、菜单和页脚在“设计模板”选项卡中编辑。在同一位置，“服务标头”将 HTML 插入到 head 中或结束 body 标记之前。对于常规 CSS 和 JavaScript，有一个单独的“CSS 和 JS”选项卡。一页的代码将添加到其编辑器中。',
    'Как задать разные телефоны и шапки для поддоменов?' => '如何为子域设置不同的电话号码和标头？',
    'Добавьте поддомен в разделе «Домены». Затем задайте отдельное значение подшаблона в разделе «Подшаблоны», выбрав нужный домен. Шапку и другие блоки меняйте кнопкой «Шаблоны» рядом с доменом. Доменная версия имеет приоритет перед общей. DNS и веб-сервер должны направлять поддомен в каталог этого сайта.' => '在“域”部分添加子域。然后通过选择所需的域在“子模板”部分中设置单独的子模板值。使用域旁边的“模板”按钮更改标题和其他块。域版本优先于通用版本。 DNS 和 Web 服务器必须将子域指向该站点的目录。',
    'Где поменять ссылки на соцсети и подписи рядом с ними?' => '在哪里可以更改社交网络的链接及其旁边的标题？',
    'Откройте «Настройки → Контакты и соцсети». Заполните адреса, подписи и телефоны. Код [soc-icons] выводит иконки всех настроенных сетей. Для отдельной ссылки используйте, например, [tg] или [vk].' => '打开“设置→联系人和社交网络”。填写地址、签名和电话号码。代码 [soc-icons] 显示所有已配置网络的图标。对于单个链接，请使用例如 [tg] 或 [vk]。',
    'Как добавить форму на страницу?' => '如何向页面添加表单？',
    'Откройте «Формы», настройте поля, обязательность, максимальную длину и текст кнопки. Сохраните форму и вставьте её код, например [form1], в HTML страницы.' => '打开表单，配置字段、必填字段、最大长度和按钮文本。保存表单并将其代码（例如 [form1]）粘贴到页面的 HTML 中。',
    'Где посмотреть заявки, если уведомление на email не пришло?' => '如果我没有收到电子邮件通知，我可以在哪里查看申请？',
    'Откройте «Сообщения». Заявки сохраняются там после успешной отправки формы. Для уведомлений проверьте адреса в поле «Кому» в почтовом шаблоне формы и работу функции mail() на хостинге.' => '打开消息。成功提交表格后，申请将保存在那里。对于通知，请检查表单邮件模板中“收件人”字段中的地址以及主机上 mail() 功能的功能。',
    'Как настроить письмо и отправку копий?' => '如何写信并发送副本？',
    'Откройте нужную форму и найдите блок «Почтовый шаблон». Укажите адреса в полях «Кому» и «Копии (Cc)» через запятую. В теме и тексте используйте ключи полей в фигурных скобках, например Привет {name}! Кнопки под текстом вставляют выбранную переменную. Пустые тема или текст используют стандартное уведомление.' => '打开所需的表单并找到“邮件模板”块。在“收件人”和“副本（抄送）”字段中输入地址，以逗号分隔。在主题和正文中，使用大括号中的字段键，例如 Hello {name}！文本下方的按钮插入选定的变量。空白主题或文本使用标准通知。',
    'Почему форма отклонила сообщение или просит «Я не робот»?' => '为什么表单拒绝该消息或询问“我不是机器人”？',
    'Проверьте обязательные поля, длину, формат телефона и email. В полях свободного ввода используются обычный текст без HTML и адресов сайтов. Списки запрещённых слов и IP находятся в разделе «Антиспам». Галочка «Использовать CAPTCHA» требует ключ сайта и секретный ключ Google reCAPTCHA v2 для нужного домена.' => '检查必填字段、长度、电话和电子邮件格式。免费输入字段使用纯文本，不含 HTML 或网站地址。禁止词语和 IP 列表位于反垃圾邮件部分。 “使用验证码”复选框需要所需域的站点密钥和 Google reCAPTCHA v2 密钥。',
    'Где посмотреть запросы на обратный звонок?' => '在哪里可以看到回电请求？',
    'В разделе «Обратные звонки». Компонент добавляется в страницу кодом [callback] или [callback=Вызвать мастера]. При провайдере «Нет» заявки сохраняются в админке. При настроенной телефонии доступна ручная или автоматическая передача.' => '在“回调”部分。该组件将添加到页面，代码为 [callback] 或 [callback=Вызвать мастера]。如果选择“否”提供商，应用程序将保存在管理面板中。配置电话后，可以使用手动或自动传输。',
    'Инфоблоки и компоненты' => '信息块和组件',
    'Как создать инфоблок и вывести его на страницу?' => '如何创建信息块并显示在页面上？',
    'В разделе «Инфоблоки» нажмите «Новый инфоблок», настройте столбцы и добавьте строки. В имени инфоблока и ключах столбцов используйте A–Z, a–z, 0–9, дефис или подчёркивание без пробелов. Сохраните и скопируйте код вставки из редактора инфоблока. Для списка телефонов используйте шаблон phones.' => '在“信息块”部分中，单击“新建信息块”，配置列并添加行。在信息块名称和列键中，使用 A–Z、a–z、0–9、连字符或下划线，不带空格。保存并复制信息块编辑器中的嵌入代码。如需电话列表，请使用电话模板。',
    'Как скопировать или заменить все строки инфоблока?' => '如何复制或替换信息块的所有行？',
    'Откройте инфоблок и нажмите «Править как текст». В CSV используется разделитель |. Первые три строки содержат ключи, названия и типы столбцов. Дальше идут данные. Заключайте поле с разделителем, кавычкой или переносом строки в двойные кавычки и удваивайте внутренние кавычки.' => '打开信息块并单击“编辑为文本”。 CSV 使用 |分隔符。前三行包含列的键、名称和类型。接下来是数据。将带有分隔符、引号或换行符的字段括在双引号和双内引号中。',
    'Что проверить, если галерея или список файлов пусты?' => '如果图库或文件列表为空，如何检查？',
    'Сверьте путь в коде компонента с папкой на сервере. Например, [fotos]/images/myfotos/[/fotos] использует фотографии в images/myfotos/ или templates/images/myfotos/. Для [files] проверьте расширение файла. Список поддерживаемых расширений и параметры есть в справке по компонентам.' => '检查组件代码中的路径与服务器上的文件夹。例如，[fotos]/images/myfotos/[/fotos] 使用 images/myfotos/ 或 templates/images/myfotos/. 中的照片 对于 [files]，请检查文件扩展名。可以在组件帮助中找到支持的扩展和参数的列表。',
    'Почему запрос с ?ajax=1 возвращает 403?' => '为什么使用 ?ajax=1 的请求返回 403？',
    'Фрагмент страницы требует действующего публичного сеанса и токена на том же сайте. Для подгрузки внутри сайта используйте window.siteFetchContent(), которая передаёт токен. Для обычного перехода открывайте адрес страницы без параметра ajax.' => '页面片段需要同一站点上的有效公共会话和令牌。要在站点内部加载，请使用 window.siteFetchContent()，它会传输令牌。对于正常的转换，打开不带ajax参数的页面地址。',
    'Обновления и резервная копия' => '更新和备份',
    'Как обновить движок установленного сайта?' => '如何更新已安装站点的引擎？',
    'В «Настройки → Обновления» сравните установленную версию с последней версией из GitHub, затем нажмите «Обновить движок». Если GitHub недоступен, админка показывает версию, которую удалось проверить в прошлый раз. Для ручного обновления передайте архив php-site-update.zip команде php update.php. Пакет обновления заменяет файлы движка и штатные шаблоны. Свои PHP-шаблоны храните в templates/local/.' => '在“设置”→“更新”中，将安装的版本与 GitHub 中的最新版本进行比较，然后单击“更新引擎”。如果 GitHub 不可用，管理面板将显示上次检查的版本。要手动更新，请将 php-site-update.zip 存档传递给 php 命令 update.php。更新包替换了引擎文件和标准模板。将您的 PHP 模板存储在 templates/local/. 中',
    'Что скопировать перед обновлением или переносом?' => '在升级或迁移之前我应该​​复制什么？',
    'Сделайте копию всего каталога сайта вместе со скрытыми файлами. Страницы находятся в корне и их каталогах, инфоблоки в data/, файлы настроек и учётной записи в admin/. Сохраните также свои шаблоны, загруженные изображения, сообщения и заявки. В копию входят секреты настроек, поэтому храните её вне публичного каталога.' => '复制整个站点目录以及隐藏文件。页面位于根目录及其目录中，信息块位于 data/ 中，设置和帐户文件位于 admin/. 中。还可以保存您的模板、上传的图像、消息和请求。该副本包含配置机密，因此请将其保存在公共目录之外。',
    'Что проверить, если админка не может сохранить изменения?' => '如果管理面板无法保存更改，应该检查什么？',
    'Сначала прочитайте сообщение рядом с формой. При конфликте изменений скопируйте свои правки и откройте редактор заново. При ошибке записи попросите хостинг проверить права записи процесса PHP в нужную папку и файл admin/write-lock.php. При ошибке обновления проверьте доступ сервера к GitHub и наличие PHP Zip и OpenSSL.' => '首先阅读表格旁边的消息。如果更改发生冲突，请复制您的编辑内容并再次打开编辑器。如果出现写入错误，请托管检查所需文件夹和文件 admin/write-lock.php. 中 PHP 进程的写入权限。如果更新失败，请检查服务器对 GitHub 的访问以及 PHP Zip 和 OpenSSL 的可用性。',
