    'Укажите действительный email.' => '请输入有效的电子邮件。',
    'Укажите полный номер телефона, включая код страны.' => '请提供您的完整电话号码，包括国家/地区代码。',
    'Выберите один из предложенных вариантов.' => '选择建议的选项之一。',
    'Не удалось открыть functions.php в редакторе.' => '无法在编辑器中打开 functions.php。',
    'Баннеры и редактор изображений' => '横幅和图像编辑器',
    'Настройте наборы и кадры в «Компонентах». Можно взять фотографии из папки, задать подпись, кнопку со ссылкой, форму или обратный звонок, и выбрать время показа. В режиме правки кнопки кадра открывают его настройки. Вставка изображения открывает папки, загрузку, удаление и создание копии с поворотом или изменённым размером. Для создания копии нужен GD. Выбор Font Awesome показывает значки и поддерживает поиск по имени.' => '在组件中设置集和框架。您可以从文件夹中拍摄照片，设置标题、带有链接的按钮、表单或回调，并选择显示时间。在编辑模式下，框架按钮可打开其设置。插入图像会打开文件夹、下载、删除并创建旋转或调整大小的副本。要创建副本，您需要 GD。 Font Awesome 选择显示图标并支持按名称搜索。',
    'Банери та редактор зображень' => 'Baneri 和图像编辑器',
    'Керуйте наборами й кадрами в «Компонентах». Беріть фото з папки, задавайте підпис і кнопку з посиланням, формою або зворотним дзвінком та встановлюйте час показу. У режимі редагування доступні дії кадру. Вибір зображень дає змогу переглядати папки, завантажувати, видаляти й створювати повернуті або масштабовані копії за допомогою GD. Значки Font Awesome можна знайти за назвою.' => '在“组件”中创建框架集。从文件夹中拍摄照片，设置标题和带有消息、表格或回电的按钮，并设置显示时间。编辑模式有可用的框架。选择图像后，您可以使用 GD 查看文件夹、查看、删除以及创建旋转或缩放副本。 Font Awesome 图标可以通过其名称来识别。',
    'Вставка изображения требует выбранного файла или URL. По клику на картинку открываются её размеры, выравнивание, четыре отступа и CSS. Выравнивание выбранной картинки применяется отдельно от текста. При переходе в HTML блочная разметка выводится по строкам. «Список страниц раздела [list-pages]» находится в списке компонентов. Логотип CMS в шапке админки и в подвале использует цвета текущей темы.' => '插入图像需要选定的文件或 URL。单击图像即可显示其尺寸、对齐方式、四个边距和 CSS。所选图像的对齐方式与文本分开应用。切换到 HTML 时，块标记会逐行显示。 “[list-pages] 部分的页面列表”位于组件列表中。管理页眉和页脚中的 CMS 徽标使用当前主题的颜色。',
    'Виберіть файл або URL для вставлення зображення. Натисніть картинку для налаштування розміру, вирівнювання, чотирьох відступів і CSS. Вирівнювання зображення незалежне від тексту. У режимі HTML блоки подано по рядках. [list-pages] є в списку компонентів. Логотип CMS використовує кольори теми.' => '选择文件或 URL 以插入图像。插入图像以调整大小、对齐方式、输入和 CSS。图像的验证独立于文本。在 HTML 模式下，块以行的形式呈现。 [list-pages] 位于组件列表中。 CMS 徽标 vikoryst 颜色主题。',
    'В списках вставки автоматически появляются сохранённые формы, шаблоны, подшаблоны и зарегистрированные компоненты при повторном открытии редактора. ID нового набора баннеров допускает A–Z, a–z, дефис и подчёркивание. После загрузки изображений в папку [banners] рядом с каждым файлом появляется ссылка «Редактировать кадр».' => '当您重新打开编辑器时，保存的表单、模板、子模板和注册的组件会自动显示在插入列表中。新的横幅集 ID 允许使用 A-Z、a-z、连字符和下划线。将图像上传到 [banners] 文件夹后，每个文件旁边会出现一个“编辑框架”链接。',
    'Збережені форми, шаблони, підшаблони й зареєстровані компоненти з’являються після повторного відкриття редактора. ID нового набору банерів допускає A–Z, a–z, дефіс і підкреслення. Після завантаження зображень до папки [banners] біля кожного файлу є посилання «Редагувати кадр».' => '重新打开编辑器后，会出现保存的表单、模板、子模板和注册组件。一组新横幅的 ID 允许使用 A–Z、a–z、连字符和重音符号。单击图像到皮肤文件文件夹 [banners] 后，系统会要求您“编辑框架”。',
    'Поиск' => '搜索',
    'В «Настройки → Основные» выберите вид поиска: выключен, компактный с лупой или расширенный. Поле поиска в шапке админки ведёт к нужным настройкам. Индекс обновляется после правок в админке и может перестраиваться по расписанию для изменений по FTP. В индекс входят текст страниц, вложенные страницы и инфоблоки; произвольный PHP при индексации пропускается.' => '在“设置 → 常规”中选择搜索类型：关闭、带放大镜的紧凑型或扩展型。管理标题中的搜索字段可引导至所需的设置。在管理面板中进行编辑后，索引会更新，并且可以通过 FTP 按计划重建索引。索引包括页面文本、子页面和信息块；索引过程中会跳过任意​​ PHP。',
    'Раскройте модуль для просмотра настроек и списка страниц с его вставкой. Через «Создать модуль» добавьте имя, имя файла и тело функции PHP. Возвращаемая строка вставляется кодом [php]имя[/php]. При переименовании файла код вставки сохраняется. CodeMirror включается в разделе библиотек.' => '展开模块以查看设置和包含其插入的页面列表。通过“创建模块”添加 PHP 函数的名称、文件名和主体。返回的行插入代码为 [php]name[/php]。重命名文件时，嵌入代码将被保存。 CodeMirror 包含在库部分中。',
    'Шаблоны и переводы' => '模板和翻译',
    'Можно отменить до восьми изменений каждого шаблона и вернуть исходный PHP для общих настроек и каждого домена. Чтобы изменить HTML, выберите «Свой HTML». Пользовательские PHP-шаблоны размещайте в templates/local/. Переключатель языков виден даже при создании перевода, а сохранённые переводы перемещаются вместе со страницей.' => '对于每个模板，您最多可以撤消八次更改，并将常规设置和每个域恢复为原始 PHP。要更改 HTML，请选择自定义 HTML。将自定义 PHP 模板放置在 templates/local/. 中 即使在创建翻译时语言切换器也是可见的，并且保存的翻译会随页面移动。',
    'Интеграции и обслуживание' => '集成和维护',
    'В настройках CAPTCHA, карт, телефонии и аналитики есть ссылки на кабинеты и инструкции провайдеров. URL HTTP API обратного звонка и токен можно задать в админке. Подшаблоны зарегистрированного поддомена сохраняются при переходе на основной домен. Планировщик хостинга должен запускать php update.php --scheduled каждые 15 минут.' => '在验证码、地图、电话和分析设置中，有指向提供商办公室和说明的链接。回调 HTTP API URL 和令牌可以在管理面板中设置。当移动到主域时，已注册子域的子模板将被保留。托管调度程序应每 15 分钟运行一次 php update.php --scheduled。',
    'Пошук' => '搜索',
    'В основних налаштуваннях можна вимкнути пошук або вибрати лупу чи розгорнуте поле. У шапці адмінки є пошук налаштувань. Індекс оновлюється після правок; для FTP доступний розклад. Індексуються вкладені сторінки й інфоблоки; PHP-модулі не запускаються.' => '在主要设置中，您可以振动搜索或振动 lupu 并启动字段。管理员的头正在搜索中。编辑后更新索引；有一个可用于 FTP 的文件夹。页面贡献和信息块已建立索引； PHP 模块不启动。',
    'Модулі PHP' => 'PHP 模块',
    'Розкрийте модуль, щоб переглянути налаштування та сторінки, де його вставлено. Створіть модуль, вкажіть ім’я файлу та тіло функції. Зміна імені файлу зберігає код [php]id[/php]. Підсвічування CodeMirror вмикається у бібліотеках.' => '打开模块查看其插入的设置和页面。创建一个模块，输入文件名和函数体。更改文件名会保存代码 [php]id[/php]。 CodeMirror 背光在库中可用。',
    'Шаблони й переклади' => '模板和翻译',
    'Можна скасувати до восьми змін кожного шаблону та відновити початковий PHP. Історія окрема для кожного домену. Власний HTML редагується в адмінці, PHP можна розмістити в templates/local/. Перемикач мов доступний під час створення перекладу. Переклади переносяться разом зі сторінкою.' => '您最多可以对皮肤模板进行八次更改并更新原始 PHP。皮肤领域 okrema 的历史。所有HTML都可以在后台编辑，PHP可以放在templates/local/. Remix中，在翻译时可用。翻译并排传输。',
    'Інтеграції й обслуговування' => '服务整合',
    'Посилання в налаштуваннях ведуть до ключів CAPTCHA, карт, телефонії й аналітики. URL і токен HTTP API задаються в адмінці. Значення зареєстрованого піддомену діють після переходу на основний домен. Заплануйте php update.php --scheduled кожні 15 хвилин.' => '设置中的说明可通往验证码键、地图、电话和分析。 URL 和 HTTP API 令牌在 admin 中设置。注册子域名的值在转换到主域名后有效。 Schedule php update.php --预定皮肤15次。',
    'Редактирование данных на странице' => '编辑页面上的数据',
    'В режиме правки у инфоблока, формы [formX], подшаблона [tel] и других компонентов с отдельными данными есть действия «Данные» и «На весь экран». «Вид инфоблока» перечисляет зарегистрированные шаблоны вывода. В списке родительских разделов «Корневая папка» переносит раздел на верхний уровень.' => '在编辑模式下，信息块、表格[formX]、子模板[tel]等带有单独数据的组件有“数据”和“全屏”动作。 “信息块类型”列出了已注册的输出模板。在父节列表中，“根文件夹”将该节移动到顶层。',
    'Редагування даних на сторінці' => '编辑页面上的数据',
    'У режимі редагування інфоблоки, форми [formX], підшаблон [tel] та інші компоненти з редактором даних мають дії «Дані» й «На весь екран». Список виду інфоблоку містить зареєстровані шаблони. «Коренева папка» переносить розділ на верхній рівень.' => '在编辑模式下，带有数据编辑器的信息块、表格[formX]、子模板[tel]等组件显示“数据”和“全屏”显示。信息块类型列表包含已注册的模板。 “根文件夹”将该部分移动到顶层。',
    'Используйте [list-pages] для списка опубликованных страниц раздела и его подпапок. Меню языков в админке закрывается по клику вне списка или по Escape.' => '使用 [list-pages] 列出节及其子文件夹的已发布页面。可以通过单击列表外部或单击“退出”来关闭管理面板中的语言菜单。',
    'Використовуйте [list-pages] для списку опублікованих сторінок розділу та підпапок. Меню мов закривається клацанням поза списком або клавішею Escape.' => 'Vikorist [list-pages] 获取该部分和子文件夹中已发布页面的列表。单击列表或按 Esc 键可以关闭菜单。',
    'Режимы HTML и «Визуальный редактор» переключаются вкладками. SUP, SUB и «Параграф» вставляют соответствующие элементы. Коды видны рядом с названиями компонентов. Папки медиа создаются при вставке, если пути содержат только латинские буквы, цифры, дефисы и подчёркивания в сегментах. Вкладка «Языки» ведёт к выбору дополнительных языков сайта.' => 'HTML 和可视化编辑器模式通过选项卡切换。 SUP、SUB 和段落插入适当的元素。这些代码在组件名称旁边可见。如果路径中的段仅包含拉丁字母、数字、连字符和下划线，则在插入时创建媒体文件夹。 “语言”选项卡可以选择其他站点语言。',
    'Вкладки HTML і «Візуальний редактор» перемикають режими. SUP, SUB та «Параграф» вставляють відповідні елементи. Біля назв компонентів показано коди. Папки створюються під час вставлення. Назви папок містять латинські літери, цифри, дефіс і підкреслення. Вкладка «Мови» веде до налаштувань мов сайту.' => 'HTML 和可视化编辑器选项卡可切换模式。 SUP、SUB 和“段落”插入附加元素。显示了组件名称的代码。文件夹一插入就会创建。使用拉丁字母、数字、连字符和重音符号命名文件夹。 “电影”选项卡允许您自定义您的电影网站。',
    'В HTML и визуальном редакторе значки форматируют текст, добавляют H1–H5 и списки. Установите курсор и выберите отдельно шаблон, компонент, изображение или иконку. Для форм доступны сохранённые коды, а для компонентов — их параметры. Вставка Font Awesome доступна при включённой библиотеке.' => '在 HTML 和可视化编辑器中，图标格式化文本、添加 H1–H5 和列表。 Установите курсор и выберите отдельно шаблон, компонент, изображение или иконку.保存的代码可用于表单，其参数可用于组件。启用库后，Font Awesome 插入即可使用。',
    'У HTML і візуальному редакторі значки форматують текст, додають H1–H5 і списки. Поставте курсор і виберіть шаблон, компонент, зображення або іконку. Доступні збережені форми та параметри компонентів. Іконки Font Awesome доступні, коли бібліотека увімкнена.' => '在 HTML 和可视化编辑器中，图标格式化文本、添加 H1–H5 和列表。放置光标并选择模板、组件、图像或图标。可以保存表单和组件参数。当库关闭时，Font Awesome 图标可用。',
    'Перетащите за значок ⠿, чтобы изменить порядок на одном уровне. Для одной страницы откройте «Переместить страницу» в её настройках. Значок рядом с папкой открывает выбор родительского раздела. Выберите другой раздел или корневую папку и нажмите «Переместить папку». Папка переносится со всеми вложенными страницами и файлами. Проверьте ссылки и [include], указывавшие на старые адреса.' => '拖动⠿图标可更改同一级别内的顺序。对于一页，在其设置中打开“移动页面”。文件夹旁边的图标可打开父部分的选择。选择不同的分区或根文件夹，然后单击移动文件夹。该文件夹与所有附加的页面和文件一起传输。检查指向旧地址的链接和 [include]。',
    'Перетягніть значок ⠿, щоб змінити порядок на одному рівні. Одну сторінку можна перемістити в її налаштуваннях. Значок поруч із папкою відкриває вибір батьківського розділу. Виберіть інший розділ або корінь і натисніть «Перемістити папку». Папка переміщується з усіма сторінками й файлами. Перевірте посилання та [include] зі старими адресами.' => '拖动 ⠿ 图标可更改一级的顺序。在这些设置中可以移动一侧。 “文件夹中的手”图标可打开父亲部分的选择。选择另一个部分或根目录，然后单击“移动文件夹”。该文件夹与其所有页面和文件一起移动。请使用旧地址将您的消息恢复至 [include]。',
    'Главная и политика конфиденциальности' => '家庭和隐私政策',
    'Откройте «Шаблоны оформления» для правки главной и страницы /privacy.php. Код [page-content] выводит содержимое главной. В политике [site-name] и [site-url] берут название и публичный адрес из «Настройки → Основные». Дополните начальный текст сведениями о вашем сайте и обработке данных.' => '打开“设计模板”编辑主页和/privacy.php页面。代码[page-content]显示主页的内容。在策略 [site-name] 和 [site-url] 中，从“设置→常规”中获取名称和公共地址。使用有关您的站点和数据处理的信息完成初始文本。',
    'Cookie и возврат наверх' => 'Cookie 并返回顶部',
    'В подвале [conf-policy] даёт ссылку на политику, [cookies] открывает настройки, а [top] прокручивает страницу вверх. Аналитика и встроенные карты CMS ждут согласия. Скрипты, вручную добавленные в шаблоны или служебные заголовки, требуют собственной настройки.' => '在页脚中，[conf-policy] 提供指向策略的链接，[cookies] 打开设置，[top] 滚动到页面顶部。分析和内置 CMS 地图正在等待达成协议。手动添加到模板或服务标头的脚本需要自己的配置。',
    'Редактор functions.php' => '编辑functions.php',
    'Откройте «Шаблоны оформления → Функции» после вкладки «Служебные заголовки». Добавляйте замыкания в возвращаемый массив. В PHP-шаблоне вызовите `translit("Москва")` или `ew_call("translit", "München")`. В HTML вставьте [func=translit value="Москва и München"]. Пример выдаёт `Moskva i Muenchen`.' => '打开“服务标题”选项卡后的“设计模板→功能”。将闭包添加到返回的数组中。在 PHP 模板中，调用 `translit("Москва")` 或 `ew_call("translit", "München")`。在 HTML 中插入 [func=translit value="Москва и München"]。该示例生成 `Moskva i Muenchen`。',
    'Редактирование штатных шаблонов' => '编辑标准模板',
    'В «Шаблонах оформления» поле уже содержит исходник PHP и HTML с подсветкой. При редактировании штатного шаблона выбирается «Свой PHP». Сохранение создаёт пользовательскую версию. Кнопками рядом с шаблоном можно отменить последнюю правку или восстановить исходник.' => '在“设计模板”字段中已经包含突出显示的 PHP 和 HTML 源代码。编辑标准模板时，选择“自定义 PHP”。保存会创建自定义版本。使用模板旁边的按钮，您可以撤消上次编辑或恢复原始内容。',
    'Проверка PHP перед сохранением' => '保存前 PHP 检查',
    'Редакторы шаблонов оформления, модулей и functions.php проверяют синтаксис командой `php -l`. При ошибке остаётся предыдущая версия. Для выбора PHP CLI на сервере используется переменная `SITE_PHP_LINT_BINARY`.' => '设计模板、模块和 functions.php 编辑器使用 `php -l` 命令检查语法。如果出现错误，则保留以前的版本。要选择服务器上的 PHP CLI，请使用 `SITE_PHP_LINT_BINARY` 变量。',
    'Подсветка и компактный поиск' => '背光和紧凑搜索',
    'CodeMirror включён по умолчанию на новой установке. Настройка находится в «Библиотеки и шрифты». В компактном поиске поле раскрывается влево, крестик очищает строку, а клавиша Enter запускает поиск.' => '新安装时默认启用 CodeMirror。该设置位于“库和字体”中。在紧凑搜索中，字段向左扩展，十字清除该行，然后按 Enter 键开始搜索。',
    'Меню админки и панель правки' => '管理菜单和编辑面板',
    'Меню под шапкой админки и панель правки на сайте показывают иконки с подписями. На узком экране остаются иконки. Подсказки открываются при наведении и при фокусе с клавиатуры на узком экране. «Скрыть» находится рядом с остальными действиями страницы. Переключатель «Режим правки» расположен справа.' => '管理面板标题下的菜单和网站上的编辑面板显示带有标题的图标。图标保留在窄屏幕上。悬停时工具提示会打开，键盘会聚焦在窄屏幕上。 “隐藏”位于其余页面操作旁边。编辑模式开关位于右侧。',
    'Описание и код PHP-модуля' => 'PHP模块说明及代码',
    'В «PHP-модулях» краткое описание предназначено для обычного текста. Вставляйте тело функции в отдельное поле «Исходный код · PHP».' => '在“PHP 模块”中，简短描述适用于纯文本。将函数主体粘贴到单独的字段“源代码·PHP”中。',
    'Кнопки в шапке админки' => '管理标题中的按钮',
    'Глобус открывает сайт, стрелка завершает сеанс администратора. На телефоне видны только иконки. Подсказки появляются при наведении или фокусе с клавиатуры.' => '地球仪打开站点，箭头结束管理员会话。手机上仅显示图标。当您将鼠标悬停或使用键盘聚焦时，会出现工具提示。',
    'Кнопки в шапці адмінпанелі' => '管理面板标题中的按钮',
    'Глобус відкриває сайт, стрілка завершує сеанс адміністратора. На телефоні видно лише іконки. Підказки з’являються при наведенні або фокусі з клавіатури.' => '地球仪打开站点，箭头结束管理员会话。在手机上只能看到图标。当您将鼠标悬停或聚焦在键盘上时，会出现提示。',
    '«Содержимое», «Формы и заявки» и «Сайт и сервисы» открываются сразу. Под шапкой выбранного раздела доступны его вкладки.' => '“内容”、“表格和应用程序”以及“网站和服务”立即开放。其选项卡位于所选部分的标题下。',
    '«Вміст», «Форми й заявки» та «Сайт і сервіси» відкриваються відразу. Під головним меню відображаються вкладки вибраного розділу.' => '“相反”、“申请表”和“网站和服务”立即开放。所选部分的选项卡显示在主菜单下。',
    'Вставьте [bread-crumbs] или [search] в HTML главной страницы (index.php) или шаблона. Блок появится в указанном месте один раз. Галочка хлебных крошек и режим поиска действуют и для вставленных тегов. [privacy] выводит ссылку на /privacy/. Текст политики редактируется в разделе «Страницы».' => '将 [bread-crumbs] 或 [search] 插入主页 (index.php) 或模板的 HTML 中。该块将在指定位置出现一次。面包屑复选框和搜索模式也适用于插入的标签。 [privacy] 显示指向 /privacy/ 的链接。政策文本在“页面”部分进行编辑。',
    'Вставте [bread-crumbs] або [search] в HTML головної сторінки (index.php) чи шаблону. Блок з’явиться один раз у вказаному місці. Налаштування навігаційного ланцюжка й пошуку діють для тегів. [privacy] веде на /privacy/. Текст політики редагується в розділі «Сторінки».' => '将 [bread-crumbs] 或 [search] 插入模板首页 (index.php) 的 HTML 中。该块将在指定位置出现一次。调整导航工具并搜索标签。 /privacy/ 上的 [privacy]。该政策的文本在“故事”部分进行编辑。',
    'Язык админки и справки' => '管理和帮助语言',
    'В региональных настройках включите нужные языки. Меню выбора языка в шапке меняет интерфейс и справку, сохраняя текущий раздел. Тексты страниц и значения ваших настроек хранятся в исходном виде.' => '在区域设置中，启用所需的语言。标题中的语言选择菜单会更改界面和帮助，同时保留当前部分。页面文本和您的设置值以其原始形式存储。',
    'Оформление подвала' => '地下室装修',
    'Код [author] выводит подпись Eurowebcart CMS Lite, имя автора Бандалетов Павел и ссылку на GitHub. Чтобы выбрать место подписи в собственном HTML подвала, вставьте [author] в нужную строку.' => '代码 [author] 显示签名 Eurowebcart CMS Lite、作者姓名 Бандалетов Павел 以及 GitHub 的链接。要选择在自定义 HTML 页脚中放置签名的位置，请将 [author] 粘贴到相应的行中。',
    'Подсветка в режиме правки' => '编辑模式下背光',
    'Наведите указатель на ссылку «Править компонент» или установите на неё фокус с клавиатуры. Рамка выделит вывод именно этой вставки.' => '将鼠标悬停在“编辑组件”链接上或将键盘焦点设置到它。该框架将突出显示该特定插入的输出。',
    'Где изменить поиск' => '在哪里更改搜索',
    'В «Настройки → Основные» выберите вид поиска. В «Обслуживании» можно переиндексировать страницы, а поле в шапке админки ищет по настройкам.' => '在“设置→常规”中选择搜索类型。在“维护”中，您可以重新索引页面，管理标题中的字段可以按设置搜索。',
    'Результаты и подсказки' => '结果和提示',
    'Поиск выводит по 20 пронумерованных результатов на страницу. Компактная строка раскрывается влево от лупы, а значок Enter расположен внутри поля. Поиск в шапке админки предлагает прямые ссылки на настройки.' => '搜索每页显示 20 个编号结果。紧凑的线条扩展到放大镜的左侧，并且 Enter 图标位于该字段内。管理标题中的搜索提供了指向设置的直接链接。',
    'Таблица из инфоблока' => '信息块中的表',
    'График из инфоблока' => '信息块中的图表',
    'Тип графика' => '图表类型',
    'Столбец подписей' => '签名栏',
    'Столбцы значений' => '值列',
    'Заголовок графика' => '图标题',
    'Выберите инфоблок и столбец значений для графика.' => '为图表选择一个信息块和一个值列。',
    'Включите Chart.js в настройках библиотек.' => '在库设置中启用 Chart.js。',
    'Столбчатый' => '柱状',
    'Горизонтальный' => '水平的',
    'Линейный' => '线性',
    'Круговой' => '圆',
    'Кольцевой' => '环形',
    'Лепестковый' => '花瓣',
    'Полярный' => '极性',
    'В редакторе страницы откройте «Вставить компонент» и выберите таблицу или график. Для графика включите Chart.js в настройках, выберите столбец подписей и отметьте числовые столбцы (Число или Цена). Круговой, кольцевой и полярный графики используют один ряд неотрицательных значений. При отключённой библиотеке посетители увидят таблицу.' => '在页面编辑器中，打开插入组件并选择表格或图形。对于图表，在设置中启用 Chart.js，选择标签列并检查数字列（数字或价格）。饼图、圆环图和极坐标图使用单个非负值系列。当图书馆被禁用时，访客将看到一张桌子。',
    'Таблиця з інфоблоку' => '带信息块的表',
    'Діаграма з інфоблоку' => '带信息块的图表',
    'Інфоблок' => '信息块',
    'Тип діаграми' => '图表类型',
    'Стовпець підписів' => '一百个签名',
    'Стовпці значень' => '斯托夫奇的意思',
    'Заголовок діаграми' => '图表中的标题',
    'Виберіть інфоблок і стовпець значень.' => '选择信息块和其他值。',
    'Увімкніть Chart.js у налаштуваннях бібліотек.' => '在配置的库上单击 Chart.js。',
    'Стовпчаста' => '斯托夫查斯塔',
    'Горизонтальна' => '水平的',
    'Лінійна' => '利内亚',
    'Кругова' => '克鲁戈娃',
    'Кільцева' => '基尔采娃',
    'Пелюсткова' => '佩柳斯特科娃',
    'Полярна' => '波拉纳',
    'У редакторі сторінки відкрийте «Вставити компонент» і виберіть таблицю чи діаграму. Для діаграм увімкніть Chart.js, виберіть стовпець підписів і стовпці типу «Число» або «Ціна». Кругова, кільцева і полярна діаграми використовують один ряд невід’ємних значень. Без бібліотеки відображається таблиця.' => '在页面编辑器中，打开“插入组件”并选择一个表格或图表。对于图表，按 Chart.js，选择签名和列类型“数字”或“价格”。圆图、圆图和极坐标图显示一系列未知值。如果没有库，则显示该表。',
    'В «Интеграциях» укажите ID JivoSite, Microsoft Clarity и Umami Cloud, код Botfaqtor или входящий вебхук Slack. Ссылки на инструкции находятся рядом с полями. В Zadarma проверьте баланс, отправьте тестовое SMS или закажите тестовый звонок по международному номеру. SMS и звонок могут тарифицироваться. Для [payment] вставьте готовые платёжные ссылки ЮMoney, PayPal и СБП. Статус оплаты проверяется в кабинете провайдера.' => '在“集成”中，指定 JivoSite、Microsoft Clarity 和 Umami Cloud ID、Botfaqtor 代码或 Slack 传入 Webhook。说明链接位于字段旁边。在扎达玛，检查您的余额、发送测试短信或拨打国际号码进行测试呼叫。短信和通话可能需要付费。对于 [payment]，插入现成的付款链接 YuMoney、PayPal 和 SBP。付款状态在提供商的帐户中检查。',
    'В «Інтеграціях» вкажіть ID JivoSite, Microsoft Clarity й Umami Cloud, код Botfaqtor або вебхук Slack. Інструкції поруч із полями. У Zadarma можна перевірити баланс, надіслати тестове SMS або здійснити дзвінок. SMS і дзвінок можуть тарифікуватися. Для [payment] вставте посилання ЮMoney, PayPal і СБП. Статус перевіряйте в кабінеті провайдера.' => '在“集成”中输入 JivoSite、Microsoft Clarity 和 Umami Cloud、Botfaqtor 代码或 Slack webhook 的 ID。字段中给出了说明。在 Zadarma，您可以检查余额、发送测试短信或拨打电话。短信和电话可能需要缴纳关税。对于 [payment]，请插入以下详细信息：YuMoney、PayPal 和 SBP。检查提供商帐户中的状态。',
    'Служебные файлы, карты и шаблоны' => '服务文件、地图和模板',
    'Откройте «Обслуживание → Служебные файлы». Здесь редактируются .htaccess, robots.txt и sitemap.xml. Генерация sitemap.xml берёт опубликованные страницы с галочкой «Показывать в карте сайта». Для .htaccess доступна предыдущая версия.' => '打开“维护→服务文件”。这里编辑.htaccess、robots.txt和sitemap.xml。生成 sitemap.xml 会使用“在站点地图中显示”复选框获取已发布的页面。以前的版本可用于 .htaccess。',
    'Заполните широту и долготу на странице. [map] покажет её точку, [maps] соберёт точки опубликованных страниц. В обоих тегах center задаёт центр, а zoom — масштаб. Интерактивная карта использует провайдера из «Интеграций».' => '在页面上填写纬度和经度。 [map]将显示其积分，[maps]将收集已发布页面的积分。在这两个标签中，center 指定中心，zoom 指定比例。交互式地图使用 Integrations 的提供程序。',
    'Под шапкой выводится [main-menu] с выпадающими подразделами. В «Шаблонах оформления» создайте свой шаблон и настройте видимость на мобильных и компьютерах. В «Подшаблонах» кнопка «+ Добавить домен» ведёт к форме добавления. Для ссылки на политику используйте [privacy].' => '带有下拉小节的 [main-menu] 显示在标题下方。在设计模板中，创建您自己的模板并配置移动设备和桌面设备上的可见性。在“子模板”中，“+ 添加域”按钮会导致添加表单。要参考该策略，请使用 [privacy]。',
    'Службові файли, карти й шаблони' => '服务文件、地图和模板',
    'Відкрийте «Обслуговування → Службові файли» для редагування .htaccess, robots.txt і sitemap.xml. До XML-карти потрапляють опубліковані сторінки з відповідною позначкою. Попередню версію .htaccess можна відновити.' => '打开“维护→服务文件”编辑.htaccess、robots.txt和sitemap.xml。带有确认图标的已发布页面显示在 XML 映射中。可以更新以前版本的.htaccess。',
    'Задайте широту й довготу. [map] показує точку сторінки, а [maps] — точки всіх опублікованих сторінок. center і zoom задають центр і масштаб. Провайдер вибирається в інтеграціях.' => '设置纬度和经度。 [map]显示该页面的点，[maps]显示所有已发布页面的点。中心和缩放设置中心和比例。提供商是在集成中选择的。',
    '[main-menu] — меню під шапкою з розкривними підрозділами. У шаблонах оформлення створюйте власні й задавайте видимість на мобільних та комп’ютерах. У підшаблонах кнопка додавання домену відкриває форму. Для посилання на політику використовуйте [privacy].' => '[main-menu] - 标题下带有开放式符号的菜单。对于设计模板，创建选项并设置移动设备和计算机上的可见性。在子模板中，添加域按钮可打开表单。要参与政治，请使用 [privacy]。',
    'Выбор точки на карте' => '在地图上选择一个点',
    'В кабинете Яндекс Карт создайте ключ для продукта «JavaScript API» в разделе «Карты». Ограничьте ключ доменом по HTTP Referer. При включённом провайдере на вкладке «Карты» страницы нажмите «Выбрать на карте», поставьте точку и перенесите её координаты в поля.' => '在您的 Yandex 地图帐户中，为“地图”部分中的“JavaScript API”产品创建密钥。将密钥限制为 HTTP Referer 域。打开提供程序后，在页面的“地图”选项卡上，单击“在地图上选择”，放置一个点并将其坐标传输到字段。',
    'Вибір точки на карті' => '在地图上选择一个点',
    'У кабінеті Яндекс Карт створіть ключ продукту «JavaScript API» та обмежте його доменом через HTTP Referer. У вкладці «Карти» сторінки виберіть точку й застосуйте координати.' => '在您的 Yandex 地图帐户中，为“JavaScript API”产品创建密钥，并通过 HTTP Referer 将其与您的域连接。在页面的“地图”选项卡中，选择一个点并输入坐标。',
    'Очистка неиспользуемых файлов' => '清理未使用的文件',
    'Найти неиспользуемые файлы' => '查找未使用的文件',
    'Убрать выбранные файлы' => '删除选定的文件',
    'Подтвердить очистку выбранных файлов.' => '确认清理选定的文件。',
    'Сканирование ищет медиа без ссылок в сохранённом содержимом. Проверьте список и отметьте нужные файлы. Перед очисткой создаётся резервная копия. Удаление кода компонента оставляет его папку и файлы на месте.' => '扫描会查找存储内容中没有链接的媒体。检查列表并标记您需要的文件。清理之前会创建备份。删除组件的代码会保留其文件夹和文件。',
    'Кандидатов для очистки нет.' => '没有可供清洁的候选人。',
    'Очищення невикористаних файлів' => '清理脏文件',
    'Знайти невикористані файли' => '查找非维多利亚时代的文件',
    'Прибрати вибрані файли' => '浏览选定的文件',
    'Підтвердити очищення вибраних файлів.' => '确认清除选定的文件。',
    'Пошук знаходить медіа без посилань у збереженому вмісті. Перегляньте список і виберіть файли. Спочатку створюється резервна копія. Видалення коду компонента залишає папку та файли на місці.' => '尝试在不询问被救者的情况下找到媒体。浏览列表并选择文件。立即创建备份副本。远程组件代码删除站点上的文件夹和文件。',
    'Файлів для очищення немає.' => '没有要清理的文件。',
    'Правка' => '编辑',
    'Настройки страницы' => '页面设置',
    'Ключевые слова' => '关键词',
    'Активна' => '积极的',
    'Окончание активности' => '活动结束',
    'Пустые даты снимают ограничения. Используется часовой пояс сайта. Скрытую страницу нужно отдельно опубликовать.' => '空白日期消除了限制。使用该网站的时区。隐藏页面必须单独发布。',
    'Укажите корректные даты. Окончание активности должно быть позже начала.' => '请提供正确的日期。活动结束时间必须晚于开始时间。',
    'Карты выключены или отсутствует ключ выбранного сервиса.' => '地图已关闭或所选服务的密钥丢失。',
    'Настроить карты' => '设置地图',
    'карта с точкой текущей страницы.' => '与当前页面的一个点进行映射。',
    'карта со всеми точками опубликованных страниц.' => '包含已发布页面的所有点的地图。',
    'Пишите содержимое в «Правке». Адрес, меню и расписание публикации настраиваются в «Настройках страницы». Заголовки, метаописание, ключевые слова и включение в sitemap находятся в SEO. Координаты и примеры тегов находятся в «Картах».' => '在“编辑”中写入内容。地址、菜单和发布时间表在“页面设置”中配置。标题、元描述、关键字和站点地图包含在 SEO 中。坐标和示例标签可以在地图中找到。',
    'Редагування' => '编辑',
    'Налаштування сторінки' => '设置页面',
    'Ключові слова' => '关键词',
    'Початок активності' => '活动棒子',
    'Завершення активності' => '已完成的活动',
    'Порожні дати знімають обмеження. Діє часовий пояс сайту. Приховану сторінку потрібно окремо опублікувати.' => '空日期受到限制。这是该网站的时区。发布的页面需要认真发布。',
    'Вкажіть правильні дати. Завершення має бути після початку.' => '请输入正确的日期。完成可能是在玉米棒子之后。',
    'Карти' => '卡蒂',
    'Карти вимкнено або немає ключа вибраного сервісу.' => '该卡已禁用或没有所选服务的密钥。',
    'Налаштувати карти' => '纳拉什图瓦提卡蒂',
    'карта з точкою поточної сторінки.' => '地图上有一个流动侧的点。',
    'карта з точками всіх опублікованих сторінок.' => '包含所有已发布页面的点的地图。',
    'Пишіть вміст у вкладці «Редагування». Адресу, меню й розклад публікації задавайте в налаштуваннях сторінки. Заголовки, метаопис, ключові слова й додавання до sitemap містяться в SEO. Координати та приклади тегів є в карти.' => '书写而不是“编辑”选项卡。在自定义页面中指定地址、菜单和出版物布局。标题、元描述、关键字和站点地图的附加内容都包含在 SEO 中。标签的坐标和应用都在地图上。',
    'Языки' => '语言',
    'Сейчас открыта' => '现已开放',
    'Создать перевод' => '创建翻译',
    'Сначала сохраните страницу.' => '首先保存页面。',
    'Добавить подраздел' => '添加小节',
    'Новый перевод' => '新翻译',
    'Во вкладке «Языки» перечислены языки страницы. «Открыть» ведёт к сохранённой версии, «Создать перевод» открывает редактор нового перевода.' => '“语言”选项卡列出了页面的语言。 “打开”会打开已保存的版本，“创建翻译”会打开编辑器以进行新翻译。',
    'Добавить соседний раздел' => '添加相邻部分',
    'Добавить раздел в корне' => '添加一个节到根',
    'Для нового раздела выберите нужный уровень. Подраздел создаётся внутри открытого раздела, соседний — рядом с ним, корневой — на верхнем уровне сайта.' => '对于新部分，选择所需的级别。在开放部分内创建子部分，在其旁边创建相邻部分，并在站点的顶层创建根部分。',
    'Мови' => '电影',
    'Зараз відкрита' => '扎兹·维克里塔',
    'Відкрити' => '维德克里蒂',
    'Створити переклад' => '创建翻译',
    'Спочатку збережіть сторінку.' => '暂时保留侧面。',
    'Додати підрозділ' => '添加更多',
    'Новий переклад' => '新翻译',
    'На вкладці «Мови» перелічено мови сторінки. «Відкрити» веде до збереженої версії, а «Створити переклад» відкриває редактор нового перекладу.' => '“电影”选项卡包含电影页面列表。 “打开”会将您带到保存的版本，“创建翻译”将打开新翻译的编辑器。',
    'Додати сусідній розділ' => '添加快递专区',
    'Додати розділ у корені' => '在根添加一个节',
    'Підрозділ створюється всередині поточного розділу, сусідній — поруч із ним, а кореневий — на верхньому рівні сайту.' => '分段创建在流动部分的中间，水部分从中创建，根部分位于场地的上层。',
    'Поиск и кеш' => '搜索和缓存',
    'В разделе «Обслуживание» перестройте текстовый индекс после публикации или изменения страниц в админке или по FTP. Поиск показывает подсказки по открытым страницам и учитывает язык посетителя. Кеш разобранного контента выключен по умолчанию. Включайте и очищайте его там же. Сессионные формы и динамические блоки обрабатываются при каждом запросе.' => '在“维护”部分中，在管理区域或通过 FTP 发布或更改页面后重建文本索引。搜索会显示打开页面的建议，并考虑访问者的语言。默认情况下禁用已解析内容缓存。打开它并在那里清洁它。会话表单和动态块根据每个请求进行处理。',
    'Правка на сайте' => '在网站上编辑',
    'После входа над шапкой появится панель правки. Справа можно включить или выключить режим для всего сайта. Включите его, чтобы править параметры возле вставок. CSS и JS текущей страницы открываются в лайтбоксе. В админке доступны HTML и визуальный редактор, вставка кодов и AJAX-управление папками галерей и файлов с массовой загрузкой и сортировкой.' => '登录后，标题上方将出现一个编辑面板。在右侧，您可以打开或关闭整个站点的模式。打开它可以编辑插入旁边的参数。当前页面的 CSS 和 JS 在灯箱中打开。管理面板中提供 HTML 和可视化编辑器、代码插入以及画廊和文件夹的 AJAX 管理以及批量加载和排序功能。',
    'Компоненты и навигация' => '组件和导航',
    'Без параметров галерея, карусель и файлы используют общие настройки. Значения во вставке переопределяют только заданные параметры. width принимает 100, 50, 33 и 25 в процентах, допускается знак %. На телефоне блоки складываются в одну колонку. numbers=off убирает номер слайда, стрелки и свайпы остаются. Мобильное меню выезжает справа. Хлебные крошки можно выключить в разделе «Настройки → Основные».' => '如果没有参数，图库、轮播和文件将使用相同的设置。插入中的值仅覆盖指定的设置。 width 接受 100%、50%、33% 和 25%，允许使用 % 符号。在手机上，这些块堆叠成一列。 Numbers=off 删除幻灯片编号，保留箭头和滑动。移动菜单在右侧滑出。可以在“设置”→“常规”中关闭面包屑导航。',
    'Языки, оформление и цена' => '语言、设计和价格',
    'В региональных настройках выберите языки сайта и админки, валюту, форматы чисел, даты, времени и часовой пояс. index_en.php рядом с index.php задаёт перевод; без отдельного файла старый адрес откроет основной текст. Тип «Цена» в инфоблоке использует выбранную валюту. «Тема и цвета» показывает цвета сохранённых тем и меняет режим сразу. Загрузите отдельные логотипы для светлой и тёмной темы. Для Roboto Condensed и других шрифтов можно менять фразу предпросмотра.' => '在区域设置中，选择网站和管理面板的语言、货币、数字格式、日期、时间和时区。 index.php 旁边的 index_en.php 指定翻译；如果没有单独的文件，旧地址将打开正文。信息块中的“价格”类型使用所选货币。 “主题和颜色”显示已保存主题的颜色并立即更改模式。上传浅色和深色主题的单独徽标。对于 Roboto Condensed 和其他字体，您可以更改预览短语。',
    'Формы, заявки и интеграции' => '表格、应用程序和集成',
    '«Настройки → CAPTCHA» задаёт общие ключи Google reCAPTCHA v2 и включает защиту для всех обычных форм. Параметры отдельных форм остаются доступны в «Формах». Сообщения и обратные звонки идут по 20 на страницу, непрочитанные вверху. В «Интеграциях» настраиваются Zadarma, Telegram, аналитика и карты Google или Яндекса. Точки со страницы группируются на одной карте, кластеризацию можно выключить. В библиотечном лайтбоксе проверяется активная версия и доступен код вставки. CodeMirror включается отдельно и поддерживает «Авто», HTML, CSS, JS, PHP и RAW.' => '“设置 → CAPTCHA”设置 Google reCAPTCHA v2 公钥并启用对所有常规表单的保护。表格中仍然提供单个表格的选项。每页有 20 条消息和回调，未读位于顶部。在“集成”中，配置了 Zadarma、Telegram、分析和 Google 或 Yandex 地图。页面中的点被分组在一张地图上；可以关闭集群。库灯箱检查活动版本并使嵌入代码可用。 CodeMirror 单独包含，支持 Auto、HTML、CSS、JS、PHP 和 RAW。',
    'В разделе «PHP-модули» настройте название, описание и доступность проверенного модуля. В редакторе выберите его код вставки. Тестовый server-date показывает дату с региональным форматом. Исполняемый код модулей хранится в защищённом каталоге и добавляется через файловый доступ разработчика.' => '在“PHP Modules”部分，配置测试模块的名称、描述和可用性。在编辑器中，选择其嵌入代码。测试服务器日期以区域格式显示日期。模块的可执行代码存储在受保护的目录中，并通过开发人员的文件访问添加。',
    'Пошук і кеш' => '搜索和现金',
    'Після публікації або редагування через адмінку чи FTP перебудуйте текстовий індекс в «Обслуговуванні». Підказки враховують мову відвідувача та відкриті сторінки. Кеш вимкнено за замовчуванням, його можна ввімкнути й очистити там само. Форми й динамічні блоки обробляються для кожного запиту.' => '通过管理员或FTP发布或编辑后，将文本索引更改为“已维护”。确保您的语言正确并打开页面的提示。缓存洗完之后就浸泡了，可以自己在那里浸泡清洗。形成形状和动态块以用于皮肤应用。',
    'Редагування на сайті' => '在网站上编辑',
    'Після входу над шапкою доступна панель. Правий перемикач діє на весь сайт і додає кнопки правки біля вставок. CSS та JS поточної сторінки відкриваються в модальному вікні. У редакторі адмінки є HTML, візуальний режим, вставлення кодів і масове AJAX-завантаження та сортування медіа й файлів.' => '登录后，标题上方会出现一个面板。正确的混音适用于整个网站，并添加插入的编辑按钮。 CSS 和 JS 流程页面在模态窗口中打开。管理编辑器具有 HTML、可视模式、代码插入和大量 AJAX 功能以及媒体文件排序。',
    'Компоненти й навігація' => '导航组件',
    'Вставки без параметрів використовують загальні налаштування. width приймає 100, 50, 33 або 25, можна зі знаком %. На телефоні блоки стають в одну колонку. numbers=off прибирає номер слайда, гортання пальцем працює. Мобільне меню виїжджає справа. Навігаційний ланцюжок вимикається в основних налаштуваннях.' => '不带参数的插入会进行 vikoristically 调整。 width 接受 100、50、33 或 25，可能带有 % 符号。在手机上，这些块排列成一列。 Numbers=off 拾取幻灯片编号，喉部用手指工作。移动菜单显示在右侧。导航挂绳在主要设置中发生变化。',
    'Мови, оформлення та ціни' => '电影、设计和价格',
    'У регіональних налаштуваннях задайте мови сайту й адміністратора, часовий пояс, валюту та формати. index_en.php біля index.php додає переклад; без нього відкривається основний текст. Поле ціни використовує обрану валюту. Можна переглянути палітру, змінити режим теми одразу, завантажити світлий і темний логотипи та перевірити Roboto Condensed зі своєю фразою.' => '在区域设置中，设置站点的网站和管理员、时区、货币和格式。 index_en.php 从 index.php 添加翻译；没有任何内容，就会出现正文。价格字段是所选的货币。您可以查看调色板，立即更改主题模式，更改浅色和深色徽标，并用您自己的短语更改 Roboto Condensed。',
    'Форми, заявки й інтеграції' => '表格、应用程序和集成',
    'Спільні ключі Google reCAPTCHA v2 і загальне ввімкнення є в налаштуваннях CAPTCHA, окремі параметри — у формах. Повідомлення й дзвінки показуються по 20, непрочитані першими. Інтеграції охоплюють Zadarma, Telegram, аналітику та карти Google або Яндекса з кластеризацією. Тест бібліотеки й код вставлення відкриваються в модальному вікні. CodeMirror має режими «Авто», HTML, CSS, JS, PHP і RAW.' => '除了表单中的参数之外，Google reCAPTCHA v2 的附加密钥和验证码设置中的隐藏连接。一次显示 20 个已提交的呼叫，首先显示未读的呼叫。 Zadarma、Telegram、Google 和 Yandex 分析以及具有集群功能的地图集成很受欢迎。库测试和嵌入代码在模式窗口中打开。 CodeMirror 有自动、HTML、CSS、JS、PHP 和 RAW 模式。',
    'У списку модулів PHP задайте назву, опис і дозвіл на вставлення. server-date показує дату в регіональному форматі. Виконувані файли встановлюються розробником у захищену теку.' => '在 PHP 模块列表中，指定名称、描述和插入权限。 server-date 以区域格式显示日期。下载的文件是由下载者从被盗计算机上安装的。',
    'Нажмите имя папки слева, чтобы управлять разделом справа. Там можно выбрать родительский раздел, настроить обычное и мобильное меню или указать URL перехода. Пустая страница раздела показывает подразделы. В «Обслуживании» задайте правила вида /contact.html => /contacts/ и редактируйте страницы ошибок в /error/. Поиск и язык на телефоне доступны через иконки в шапке.' => '单击左侧的文件夹名称可管理右侧的部分。您可以在其中选择父部分、配置常规菜单和移动菜单，或指定转换 URL。空白部分页面显示小节。在“维护”中，设置 /contact.html => /contacts/ 等规则，并在 /error/ 中编辑错误页面。手机上的搜索和语言可通过标题中的图标进行。',
    'Натисніть назву папки, щоб керувати розділом праворуч. Там можна вибрати батьківський розділ, налаштувати звичайне й мобільне меню та вказати URL переходу. Порожня сторінка показує підрозділи. В «Обслуговуванні» задавайте правила /contact.html => /contacts/ і редагуйте сторінки помилок у /error/. Мова й пошук доступні через іконки.' => '输入文件夹名称以创建右手部分。您可以在其中选择祖国部分、自定义主要移动菜单并指定过渡的 URL。空的一面表明已损坏。在“服务”中，设置规则/contact.html => /contacts/并在/error/处编辑错误页面。可通过图标进行语言搜索。',
    'Совместимость PHP и навигация' => 'PHP 兼容性和导航',
    'Минимальная версия PHP — 7.2. Сайт и админка поддерживают PHP 8.6. Для своих PHP-модулей и шаблонов используйте синтаксис версии, установленной на сервере.' => '最低 PHP 版本为 7.2。该网站和管理面板支持 PHP 8.6。对于您的 PHP 模块和模板，请使用服务器上安装的版本的语法。',
    'Текущий пункт [bread-crumbs] раскрывает другие опубликованные разделы того же уровня, если они включены в основное меню. URL из настроек страницы используется в меню, списках разделов, хлебных крошках, результатах и подсказках поиска.' => '当前项目 [bread-crumbs] 扩展了同级别的其他已发布部分（如果它们包含在主菜单中）。页面设置中的 URL 用于菜单、部分列表、面包屑、结果和搜索建议。',
    'Корзина удаляет строку из редактора инфоблока. Удаление столбца убирает все значения этого столбца. Правки записываются при сохранении инфоблока, в том числе при автосохранении после перетаскивания.' => '回收站从信息块编辑器中删除该行。删除列会删除该列的所有值。保存信息块时会记录编辑，包括拖动后自动保存时。',
    'Сумісність PHP і навігація' => 'PHP 和导航的疯狂',
    'Мінімальна версія PHP — 7.2. Сайт і панель адміністратора підтримують PHP 8.6. Для власних модулів і шаблонів використовуйте синтаксис версії, встановленої на сервері.' => '最低 PHP 版本为 7.2。该网站和管理面板支持 PHP 8.6。对于电源模块和模板，请检查服务器上安装的版本的语法。',
    'Поточний пункт [bread-crumbs] розкриває опубліковані розділи того самого рівня, які є в головному меню. URL із налаштувань сторінки використовується в меню, списках розділів, навігаційному ланцюжку, результатах і підказках пошуку.' => '确切的项目 [bread-crumbs] 打开与主菜单相同级别的已发布部分。浏览器页面的 URL 显示在菜单、部分列表、导航栏、结果和搜索提示中。',
    'Кошик видаляє рядок у редакторі інфоблоку. Видалення стовпця прибирає всі його значення. Зміни записуються при збереженні, зокрема й при автозбереженні після перетягування.' => '猫查看信息块编辑器中的行。可见的车站剥夺了它所有的意义。保存、特写以及拖动后自动保存时都会记录变化。',
    'Продажа' => '销售',
    'Покупки' => '购买',
    'Купить' => '买',
    'Заказ' => '命令',
    'Укажите телефон или email.' => '输入您的电话或电子邮件。',
    'Перейти к оплате' => '继续付款',
    'Заявка принята.' => '申请已被接受。',
    'Проверьте поля или обновите страницу.' => '请检查字段或刷新页面。',
    'Укажите имя.' => '请提供姓名。',
    'Заявка принята' => '申请已接受',
    'Оплата принята' => '已接受付款',
    'Заказ закрыт' => '订单已关闭',
    'Отменён' => '取消',
    'На вкладке «Продажа» задайте цену и способ оплаты для страницы. Можно переопределить их для языков. Вставьте [item-price] и [item-buy-button]. Покупка появляется в списке до перехода к провайдеру. При смене статуса можно уведомить покупателя по email и по SMS через Zadarma.' => '在“销售”选项卡上，设置页面的价格和付款方式。您可以针对语言覆盖它们。插入 [item-price] 和 [item-buy-button]。在移至提供商之前，购买会显示在列表中。更改状态时，您可以通过 Zadarma 通过电子邮件和短信通知买家。',
    'Продаж' => '销售量',
    'Купити' => '买',
    'Замовлення' => '协议',
    'Ім’я' => '我是',
    'Вкажіть телефон або email.' => '输入电话或电子邮件。',
    'Перейти до оплати' => '前往付款',
    'Політика конфіденційності' => '隐私政策',
    'Заявку прийнято.' => '申请已被接受。',
    'Перевірте поля або оновіть сторінку.' => '翻转字段或刷新页面。',
    'Вкажіть ім’я.' => '输入您的名字。',
    'Заявку прийнято' => '申请已接受',
    'Оплату прийнято' => '已接受付款',
    'Відправлено' => '发送',
    'Замовлення закрито' => '请求已关闭',
    'Скасовано' => '斜',
    'Задайте ціну й спосіб оплати у вкладці «Продаж». Для мов можна вказати окремі ціни. Вставте [item-price] і [item-buy-button]. Замовлення реєструється до оплати. Статуси можуть надсилатися через email і Zadarma SMS.' => '在“销售”选项卡中设置价格和付款方式。对于 mov，您可以指定相同的价格。插入 [item-price] 和 [item-buy-button]。订单必须在付款前注册。状态可以通过电子邮件和 Zadarma 短信进行更新。',
    'Резервные копии сайта' => '站点备份',
    'Создать бэкап контента' => '创建内容备份',
    'Загрузить ZIP' => '下载压缩包',
    'ZIP хранится в закрытой папке и включает страницы, медиа, инфоблоки, настройки, свои шаблоны и PHP-модули. Учётная запись администратора и входящие заявки сохраняются отдельно. Для архивации нужно расширение PHP Zip.' => 'ZIP 存储在一个封闭的文件夹中，包括页面、媒体、信息块、设置、自定义模板和 PHP 模块。管理员帐户和传入请求单独保存。为了存档，您需要 PHP Zip 扩展。',
    'Заменить содержимое и настройки выбранной копией. Перед заменой будет создан новый бэкап текущего состояния.' => '将内容和设置替换为所选副本。在替换之前，将创建当前状态的新备份。',
    'Выровнять влево' => '左对齐',
    'Выровнять вправо' => '右对齐',
    'Убрать форматирование' => '删除格式',
    'Параметры изображения' => '图像选项',
    'Вставить ссылку' => '插入链接',
    'Вставить кнопку' => '插入按钮',
    'Новая вкладка' => '新标签页',
    'В визуальном редакторе выделите текст для выравнивания или снятия форматирования. Нажмите на изображение, чтобы открыть его параметры. Потяните за угол для изменения размера или перетащите само изображение в другое место. Для ссылки доступны URL, email, телефон и якорь. Кнопка может открыть URL, форму, обратный звонок или оплату. Для оплаты используйте ссылку провайдера на указанную сумму.' => '在可视化编辑器中，选择要对齐或删除格式的文本。单击图像打开其选项。拖动一个角来调整大小或将图像本身拖动到另一个位置。该链接提供 URL、电子邮件、电话和锚点。该按钮可以打开 URL、表单、回调或付款。要付款，请使用提供商的链接支付指定金额。',
    'Резервні копії сайту' => '网站的备份副本',
    'Створити резервну копію' => '创建备份副本',
    'Завантажити ZIP' => '有利邮政编码',
    'Скачати' => '下载',
    'Відновити' => '更新',
    'Приватний ZIP містить сторінки, медіа, інфоблоки, налаштування, власні шаблони й PHP-модулі. Обліковий запис і вхідні заявки зберігаються окремо. Потрібне розширення PHP Zip.' => '私人 ZIP 包含页面、媒体、信息块、设置、模板和 PHP 模块。帐户记录和输入请求分开存储。需要 PHP Zip 扩展名。',
    'Замінити вміст і налаштування. Спочатку буде створено копію поточного стану.' => '更换并调整。从现在开始，将创建生产工厂的副本。',
    'Вирівняти ліворуч' => '维尔尼亚提 左撇子',
    'Вирівняти праворуч' => '维尔尼亚提右手',
    'Очистити форматування' => '格式清晰',
    'Параметри зображення' => '图像参数',
    'Вставити посилання' => '按要求插入',
    'Вставити кнопку' => '插入按钮',
    'Дія' => '迪亚',
    'Нова вкладка' => '新标签页',
    'Виділіть текст для вирівнювання чи очищення форматування. Клацніть зображення, щоб відкрити параметри. Змініть розмір за кут або перетягніть зображення в тексті. Посилання підтримують URL, email, телефон і якір. Кнопка відкриває URL, форму, зворотний дзвінок або оплату за посиланням провайдера.' => '请参阅文本来验证并清除格式。单击图像打开设置。更改大小或拖动文本中的图像。请支持网址、邮箱、电话、邮箱。该按钮可根据提供商的请求打开 URL、表格、门铃或付款。',
    'Текст' => '文本',
    'Число' => '数字',
    'Дата' => '日期',
    'Да/нет' => '并不真地',
    'Не удалось прочитать старый формат инфоблока.' => '无法读取旧的信息块格式。',
    'Используйте CSV в UTF-8 размером до 512 КиБ.' => '使用 UTF-8 格式的 CSV，最大大小为 512 KiB。',
    'В первых трёх строках CSV укажите ключи, названия и типы столбцов.' => '在 CSV 的前三行中，包含键、列名称和列类型。',
    'Ключи, названия и типы должны содержать одинаковое число столбцов.' => '键、名称和类型必须包含相同数量的列。',
