    'Работа с DOM, событиями и плагинами.' => '使用 DOM、事件和插件。',
    'Сетка, кнопки, модальные окна и другие компоненты.' => '网格、按钮、模态框和其他组件。',
    'Локальные иконки для классов fa-* и кода [fa-icon=house].' => 'fa-* 类和代码 [fa-icon=house] 的本地图标。',
    'Компоненты React. Доступны через import из @mui/material.' => '反应组件。可通过从 @mui/material 导入获得。',
    'Интерактивные элементы через атрибуты x-data и x-on.' => '通过 x-data 和 x-on 属性的交互元素。',
    'Частичная загрузка страниц через атрибуты hx-get и hx-target.' => '通过 hx-get 和 hx-target 属性部分加载页面。',
    'Графики и диаграммы.' => '图表和图表。',
    'Просмотр фотографий и видео в окне поверх страницы.' => '在页面顶部的窗口中查看照片和视频。',
    'Подсветка PHP, CSS, JS и HTML в админке и на панели правки. Есть режимы «Авто» и RAW.' => '在管理面板和编辑面板中突出显示 PHP、CSS、JS 和 HTML。有“自动”和“RAW”模式。',
    'Выключено' => '离开',
    'Схема' => '方案',
