    'Стиль' => '风格',
    'Русский' => '俄语',
    'Українська' => '乌克兰',
    'Съешь еще этих мягких французских булочек да выпей чаю' => '多吃一些柔软的法式面包，喝点茶。',
    'Ще не вмерла України і слава, і воля' => '乌克兰的荣耀和自由尚未消亡',
    'Условия покупки изменились.' => '购买条款已更改。',
    'Не удалось открыть хранилище покупок.' => '无法打开购买库。',
    'Обновляется движок сайта. Откройте страницу через несколько секунд.' => '站点引擎正在更新。几秒钟后打开页面。',
    'Мой сайт' => '我的网站',
    'Бандалетов Павел' => 'Бандалетов Павел',
    'Недопустимый путь к файлу настроек.' => '设置文件的路径无效。',
    'Не удалось прочитать файл настроек.' => '无法读取设置文件。',
    'Неверный формат файла настроек.' => '设置文件格式无效。',
    'Править компонент' => '编辑组件',
    'Работает на EWC' => '由 EWC 提供支持',
    'Автор' => '作者',
    'Не удалось прочитать служебные заголовки.' => '无法读取服务标头。',
    'Неверный формат файла со стилями и скриптами.' => '样式和脚本的文件格式不正确。',
    'Страница не найдена' => '找不到页面',
    'Проверьте адрес страницы или выберите раздел в меню.' => '检查页面地址或从菜单中选择一个部分。',
    'Доступ к фрагменту разрешён только из сеанса на этом сайте.' => '仅允许从此站点上的会话访问该片段。',
    'ставки' => '费率',
    'Удалите ссылки из этого поля.' => '从此字段中删除链接。',
    'Это поле содержит запрещённое слово или выражение.' => '该字段包含禁止的单词或表达方式。',
    'Шапка, меню и подвал' => '页眉、菜单和页脚',
    'Полная страница подключает эти блоки автоматически. Общие версии редактируются в «Шаблоны оформления», а для отдельного домена — в разделе «Домены».' => '整页自动连接这些块。通用版本在“设计模板”中编辑，对于单个域，则在“域”部分中编辑。',
    'Вставка другой страницы' => '插入另一页',
    'Вставляет содержимое опубликованной страницы. Максимальная вложенность — десять уровней. Повтор страницы в одной цепочке пропускается.' => '插入已发布页面的内容。最大嵌套为十层。跳过同一链中重复的页面。',
    'Ссылки в меню' => '菜单中的链接',
    'Галочка «Показывать в меню» добавляет ссылку в штатные меню. При пустом названии берётся заголовок. Если отключить галочку у страницы папки, её вложенные страницы тоже исчезнут из меню.' => '“在菜单中显示”复选框添加到标准菜单的链接。如果名称为空，则使用标题。如果取消选中文件夹页面的复选框，其子页面也将从菜单中消失。',
    'MenuVisible: 1
Menu: Контакты' => '菜单可见：1
菜单：联系人',
    'CSS и JavaScript' => 'CSS 和 JavaScript',
    'Общий код редактируется во вкладке «CSS и JS». Код страницы редактируется в блоке «CSS и JavaScript страницы» и подключается после общего. В поля вставьте содержимое CSS и JavaScript.' => '通用代码在“CSS和JS”选项卡中编辑。页面代码在“CSS 和 JavaScript 页面”块中编辑，并包含在常规页面之后。将 CSS 和 JavaScript 内容粘贴到字段中。',
    'В разделе «Шаблоны оформления → Служебные заголовки» можно вставить общие метатеги и коды счётчиков внутрь head или перед закрывающим body. Canonical добавляется автоматически на полных страницах.' => '在“设计模板→服务标题”部分中，您可以在标题内或结束正文之前插入通用元标记和计数器代码。 Canonical 会自动添加到整页上。',
    'Иконки Font Awesome' => '字体真棒图标',
    'Подключён Font Awesome Free 7.3.1. Короткий код работает в контенте и HTML блоков оформления. Доступны стили solid, regular и brands. Добавьте рядом с иконкой текст, если она обозначает действие.' => 'Font Awesome Free 7.3.1 已连接。简短的代码适用于内容和 HTML 设计块。有纯色、常规和品牌款式可供选择。如果图标代表操作，则在图标旁边添加文本。',
    '<i class="fa-icon fa-solid fa-phone" aria-hidden="true"></i> Связаться' => '<i class="fa-icon fa-solid fa-phone" aria-hidden="true"></i> 联系方式',
    'Подключайте библиотеки в «Настройки → Библиотеки». Сохраните локальные копии нужных ресурсов через интерфейс. Font Awesome уже входит в поставку. В «Шаблоны оформления → Темы дизайна» включается готовый сайт. Цвета и шрифты открываются отдельными вкладками. Можно включить несколько семейств и сохранить их локально.' => '在“设置 → 库”中启用所需的库，并在需要时保存本地资源。Font Awesome 随系统提供。 在“设计模板 → 设计主题”中启用完整站点。站点颜色和字体有各自的选项卡，可启用多个字体并保存本地副本。',
    'Переменные, подшаблоны и дата' => '变量、子模板和日期',
    'Переменные сайта' => '站点变量',
    'Добавьте записи в «Настройки → Основные». Вставляйте ключ в текст, заголовок, название сайта или подвал.' => '将条目添加到“设置→常规”。将密钥插入文本、页眉、站点标题或页脚中。',
    'Сервис в городе [city]' => '同城服务 [city]',
    'В разделе «Подшаблоны» задайте имя, описание и значение. Для домена сначала берётся его значение, затем общее. Подшаблон может содержать HTML. В заголовках разметка убирается.' => '在子模板部分中，指定名称、描述和值。对于域，首先取其值，然后取其一般值。子模板可以包含 HTML。标头中的标记已被删除。',
    'Дата и время' => '日期和时间',
    'Часовой пояс берётся из PHP. [year] — год, [month] — месяц, [day] — день месяца, [time] — часы и минуты, [dmY] и [date] — дата ДД.ММ.ГГГГ, [datetime] — дата и время.' => '时区取自 PHP。 [year] - 年、[month] - 月、[day] - 月中的某天、[time] - 小时和分钟、[dmY] 和 [date] - 日期 DD.MM.YYYY、[datetime] - 日期和时间。',
    '© [year] [city]
Дата [dmY], время [time]' => '© [year] [city]
日期 [dmY]，时间 [time]',
    'Название CMS и автор' => 'CMS 名称和作者',
    'Код [author] выводит Eurowebcart CMS Lite, имя автора Бандалетов Павел и ссылку на GitHub. В стандартном подвале подпись появляется автоматически. В собственный HTML подвала вставьте код в нужное место.' => '代码 [author] 输出 Eurowebcart CMS Lite、作者姓名 Бандалетов Павел 以及 GitHub 的链接。在标准页脚中，签名会自动出现。在您自己的 HTML 页脚中，将代码粘贴到您想要的位置。',
    'Шаблон главной и политика' => '主页模板和政策',
    'Код [page-content] вставляет текст главной в шаблон [home]. В «Страницах» откройте /privacy/, чтобы изменить текст политики. Подстановки [site-name] и [site-url] берутся из основных настроек.' => '代码 [page-content] 将正文插入模板 [home] 中。在 Pages 中，转至 /privacy/ 编辑策略文本。替换 [site-name] 和 [site-url] 取自主设置。',
    'Ссылки и настройки в подвале' => '页脚中的链接和设置',
    'Код [privacy] выводит ссылку на /privacy/, [top] прокручивает страницу вверх, [cookies] открывает настройки согласия.' => '代码 [privacy] 显示指向 /privacy/ 的链接，[top] 将页面滚动到顶部，[cookies] 打开同意设置。',
    'Общие функции PHP' => '常用 PHP 函数',
    'В разделе «Шаблоны оформления → Функции» отредактируйте functions.php. В PHP-коде translit() или ew_call() вызывает зарегистрированную функцию. Короткий код [func=translit] доступен в содержимом и в поле «Свой HTML».' => '在“设计模板→功能”部分中，编辑functions.php。在 PHP 代码中，translit() 或 ew_call() 调用已注册的函数。短代码 [func=translit] 可在内容和“自定义 HTML”字段中找到。',
    '[func=translit value="Москва и München"]' => '[func=translit value="Москва и München"]',
    '$var = translit("Москва");' => '$var = translit("莫斯科");',
    'Карусель, фотогалерея и файлы' => '轮播、照片库和文件',
    'Показывает фотографии из папки. arrows и numbers принимают on или off, effect — slide, fade или none, fit — contain или cover.' => '显示文件夹中的照片。箭头和数字接受打开或关闭，效果 - 滑动、淡入淡出或无，适合 - 包含或覆盖。',
    'Показывает адаптивную сетку. columns — auto или число от 1 до 6, ratio — 4x3, 1x1, 16x9 или original, fit — cover или contain. captions и links включаются через on или off.' => '显示响应式网格。列 — 自动或 1 到 6 之间的数字，比率 — 4x3、1x1、16x9 或原始，适合 — 覆盖或包含。标题和链接可通过打开或关闭启用。',
    'Выводит поддерживаемые файлы. icons, size и download принимают on или off, order — asc или desc. Разрешены zip, pdf, xls, xlsx, doc, docx, png, gif, jpg, jpeg, mp4, mov и mp3.' => '列出支持的文件。图标、大小和下载接受打开或关闭、顺序 - 升序或降序。允许使用 Zip、pdf、xls、xlsx、doc、docx、png、gif、jpg、jpeg、mp4、mov 和 mp3。',
    'Формы и обратный звонок' => '表格和回电',
    'Форма [formN]' => '表格 [formN]',
    'В разделе «Формы» настройте поля, их максимальную длину, текст кнопки и получателя. «Использовать CAPTCHA» включает виджет Google reCAPTCHA v2 с проверкой ответа на сервере. Заявки отправляются через AJAX и видны в разделе «Сообщения».' => '在“表单”部分中，配置字段、最大长度、按钮文本和收件人。 “使用验证码”启用 Google reCAPTCHA v2 小部件，并在服务器上进行响应验证。请求通过 AJAX 发送，并在“消息”部分中可见。',
    'Почтовый шаблон формы' => '邮件表格模板',
    'Тема и текст хранятся отдельно для каждой формы. В почтовом шаблоне вставляйте ключи полей в фигурных скобках. Списки получателей и копий разделяются запятыми.' => '每个表单的主题和文本分别存储。在您的电子邮件模板中，在花括号中插入字段键。收件人列表和副本列表以逗号分隔。',
    'Привет {name}!
Телефон: {phone}
Сообщение: {message}' => '你好{name}！
电话：{phone}
留言：{message}',
    'Обратный звонок [callback]' => '回拨 [callback]',
    'Открывает форму с телефоном. Заявка сохраняется в разделе «Обратные звонки». Подпись кнопки можно задать в коде. С провайдером «Нет» отправка в телефонию выключена.' => '打开包含电话号码的表单。该应用程序保存在“回调”部分。按钮标签可以在代码中设置。对于“否”提供商，将禁用发送到电话。',
    '[callback]
[callback=Вызвать мастера]' => '[callback]
[callback=Вызвать мастера]',
    'Таблица и список телефонов' => '电话表和清单',
    'Создайте набор данных в разделе «Инфоблоки». В имени инфоблока и ключах столбцов разрешены A–Z, a–z, 0–9, дефис и подчёркивание. Пробелы запрещены. Шаблон table показывает таблицу, phones выводит телефонные столбцы со ссылками для звонка. Поддерживаются закрывающие коды [iblock] и [/iblock].' => '在“Infoblocks”部分创建一个数据集。信息块名称和列键中允许使用 A–Z、a–z、0–9、连字符和下划线。不允许有空格。表格模板显示表格，电话显示带有呼叫链接的电话列。支持关闭代码 [iblock] 和 [/iblock]。',
    'Общий блок и иконки' => '通用块和图标',
    '[contacts] выводит блок контактов, [phones] показывает телефоны, [soc-icons] собирает иконки всех соцсетей с настроенными ссылками.' => '[contacts] 显示联系人块，[phones] 显示电话号码，[soc-icons] 收集所有社交网络的图标以及自定义链接。',
    'Отдельные соцсети' => '个人社交网络',
    'Каждый код выводит ссылку своей соцсети. Адреса и подписи задаются в «Настройки → Контакты и соцсети».' => '每个代码都会显示其社交网络的链接。地址和签名在“设置→联系人和社交网络”中设置。',
    'Нужен путь к новому ZIP-файлу.' => '我们需要新 ZIP 文件的路径。',
    'Не удалось добавить файл в ZIP.' => '无法将文件添加到 ZIP。',
    'Не удалось сохранить ZIP обновления.' => '无法保存 ZIP 更新。',
    'Проверьте формат токена GitHub.' => '检查 GitHub 令牌格式。',
    'GitHub вернул неподдерживаемый адрес загрузки.' => 'GitHub 返回了不受支持的下载地址。',
    'Нет ответа от GitHub. Проверьте HTTPS-соединение сервера.' => 'GitHub 没有回复。检查服务器的 HTTPS 连接。',
    'GitHub не отдал файл обновления. HTTP ' => 'GitHub 没有提供更新文件。 HTTP协议',
    'Слишком много перенаправлений GitHub.' => 'GitHub 重定向过多。',
    'В репозитории указан неверный номер версии.' => '存储库的版本号不正确。',
    'В GitHub Releases нужен опубликованный релиз с тегом vX.Y.Z.' => 'GitHub 版本需要带有 vX.Y.Z 标签的已发布版本。',
    'В релизе должны быть ZIP обновления и файл его подписи.' => '该版本必须包含 ZIP 更新及其签名文件。',
    'Укажите репозиторий в SITE_GITHUB_REPO или maintenance/github.php.' => '在 SITE_GITHUB_REPO 或 maintenance/github.php. 中指定存储库',
    'Для обновления с GitHub нужны PHP-расширения Zip и OpenSSL.' => '要从 GitHub 更新，您需要 Zip 和 OpenSSL PHP 扩展。',
    'Установлена актуальная версия.' => '最新版本已安装。',
    'Укажите доверенный открытый ключ подписи обновлений.' => '指定受信任的公共更新签名密钥。',
    'Подпись обновления GitHub не прошла проверку.' => 'GitHub 更新签名验证失败。',
    'Не удалось создать временный файл обновления.' => '无法创建临时更新文件。',
    'Не удалось записать загруженное обновление.' => '无法写入下载的更新。',
    'Укажите доступный ZIP обновления. Требуется PHP-расширение Zip.' => '指定可用的 ZIP 更新。需要 Zip PHP 扩展。',
    'ZIP обновления повреждён.' => '更新 zip 已损坏。',
    'Список файлов обновления не прошёл проверку.' => '更新文件列表验证失败。',
    'Архив содержит файл за пределами движка.' => '存档包含引擎外部的文件。',
    'Не удалось проверить размер файлов обновления.' => '无法检查更新文件的大小。',
    'Контрольная сумма файла обновления не совпала.' => '更新文件校验和不匹配。',
    'Не удалось получить блокировку движка.' => '无法获得发动机锁。',
    'Движок обновлён до версии ' => '引擎已更新至版本',
    'Недопустимый путь файла обновления.' => '更新文件路径无效。',
    'Не удалось сделать резервную копию файла движка.' => '备份引擎文件失败。',
    'Не удалось подготовить файлы обновления.' => '无法准备更新文件。',
    'Не удалось заменить файл движка.' => '替换引擎文件失败。',
    'Обновление прервано, восстановление файлов завершилось с ошибкой.' => '更新被中断，文件恢复完成但出现错误。',
    'Главная' => '首页',
    'Настройки cookie' => 'Cookie 设置',
    'Выберите, какие необязательные сервисы разрешить.' => '选择允许哪些可选服务。',
    'Необходимые' => '必需的',
    'Аналитика' => '分析',
    'Встроенные карты' => '内置地图',
    'Принять все' => '接受一切',
    'Только необходимые' => '仅必要',
    'Панель администратора' => '管理面板',
    'Админка' => '行政',
    'Новый раздел' => '新版块',
    'Убрать из меню' => '从菜单中删除',
    'Показать в меню' => '在菜单中显示',
    'Режим правки' => '编辑模式',
    'Компоненты страницы' => '页面组件',
    'Перейти к содержимому' => '跳至内容',
    'Проверяем загрузку…' => '正在检查下载...',
    'Тест пройден.' => '测试通过。',
    'Библиотека не прошла проверку. Проверьте загрузку файлов.' => '该库尚未经过验证。检查您的文件上传。',
    'Меню' => '菜单',
    'Закрыть меню' => '关闭菜单',
    'Эта страница описывает обработку данных при использовании сайта.' => '本页描述使用网站时的数据处理。',
    'Сообщения и заявки' => '消息和请求',
    'Когда вы отправляете форму, сайт сохраняет введённые данные для обработки вашего обращения. Для связи по поводу данных используйте контакты на сайте.' => '当您提交表单时，网站会保存输入的数据以处理您的请求。要就数据事宜与我们联系，请使用网站上的联系人。',
    'Файлы cookie' => '曲奇饼',
    'Служебные файлы cookie нужны для сеанса, защиты форм и хранения выбранных настроек. Согласие на встроенные карты и аналитику можно изменить в подвале.' => '会话、保护表单和存储首选项需要服务 cookie。可以在页脚中更改对嵌入式地图和分析的同意。',
    'Поиск пока недоступен.' => '搜索尚不可用。',
    'Страницы результатов поиска' => '搜索结果页面',
    'Страница {page}' => '页码 {page}',
    'Найти' => '寻找',
    'Наверх' => '顶部',
    'Сделано на %s. Автор — Бандалетов Павел.' => '在 %s 上制造。作者 - Бандалетов Павел。',
    'О программе' => '关于该计划',
    'Исходный код на GitHub' => 'GitHub 上的源代码',
    'Сайт на PHP с хранением контента в файлах' => 'PHP 网站，内容存储在文件中',
    'Русский · Eurowebcart CMS Lite' => '俄语 Eurowebcart CMS Lite',
    '[Руководство](ru/readme.md)' => '[说明书](ru/readme.md)',
    '[FAQ по админке](ru/faq.md)' => '[管理员常见问题解答](ru/faq.md)',
    '[Шаблоны и компоненты](ru/templates.md)' => '[模板和组件](ru/templates.md)',
    'Мобильное меню · 1.6.7' => '移动菜单1.6.7',
    'Редактирование данных на странице · 1.6.6' => '编辑页面数据·1.6.6',
    'В режиме правки у инфоблока, формы [formX], подшаблона [tel] и других компонентов с отдельными данными есть действия «Данные» и «На весь экран». «Вид инфоблока» перечисляет зарегистрированные шаблоны вывода.' => '在编辑模式下，信息块、表格[formX]、子模板[tel]等带有单独数据的组件有“数据”和“全屏”动作。 “信息块类型”列出了已注册的输出模板。',
    'В списке родительских разделов «Корневая папка» переносит раздел на верхний уровень.' => '在父节列表中，“根文件夹”将该节移动到顶层。',
    'Используйте [list-pages] для списка опубликованных страниц раздела и его подпапок.' => '使用 [list-pages] 列出节及其子文件夹的已发布页面。',
    'Меню языков в админке закрывается по клику вне списка или по Escape.' => '可以通过单击列表外部或单击“退出”来关闭管理面板中的语言菜单。',
    'Служебные файлы, карты и шаблоны · 1.6.5' => '服务文件、地图和模板 · 1.6.5',
    'Откройте «Обслуживание → Служебные файлы».' => '打开“维护→服务文件”。',
    'Здесь редактируются .htaccess, robots.txt и sitemap.xml.' => '这里编辑.htaccess、robots.txt和sitemap.xml。',
    'Генерация sitemap.xml берёт опубликованные страницы с галочкой «Показывать в карте сайта».' => '生成 sitemap.xml 会使用“在站点地图中显示”复选框获取已发布的页面。',
    'Для .htaccess доступна предыдущая версия.' => '以前的版本可用于 .htaccess。',
    'Заполните широту и долготу на странице. [map] покажет её точку, [maps] соберёт точки опубликованных страниц.' => '在页面上填写纬度和经度。 [map]将显示其积分，[maps]将收集已发布页面的积分。',
    'В обоих тегах center задаёт центр, а zoom — масштаб.' => '在这两个标签中，center 指定中心，zoom 指定比例。',
    'Интерактивная карта использует провайдера из «Интеграций».' => '交互式地图使用 Integrations 的提供程序。',
    'Под шапкой выводится [main-menu] с выпадающими подразделами.' => '带有下拉小节的 [main-menu] 显示在标题下方。',
    'В «Шаблонах оформления» создайте свой шаблон и настройте видимость на мобильных и компьютерах.' => '在设计模板中，创建您自己的模板并配置移动设备和桌面设备上的可见性。',
    'В «Подшаблонах» кнопка «+ Добавить домен» ведёт к форме добавления.' => '在“子模板”中，“+ 添加域”按钮会导致添加表单。',
    'Для ссылки на политику используйте [privacy].' => '要参考该策略，请使用 [privacy]。',
    'В «Интеграциях» укажите ID JivoSite, Microsoft Clarity и Umami Cloud, код Botfaqtor или входящий вебхук Slack.' => '在“集成”中，指定 JivoSite、Microsoft Clarity 和 Umami Cloud ID、Botfaqtor 代码或 Slack 传入 Webhook。',
    'Ссылки на инструкции находятся рядом с полями.' => '说明链接位于字段旁边。',
    'В Zadarma проверьте баланс, отправьте тестовое SMS или закажите тестовый звонок по международному номеру. SMS и звонок могут тарифицироваться.' => '在扎达玛，检查您的余额、发送测试短信或拨打国际号码进行测试呼叫。短信和通话可能需要付费。',
    'Для [payment] вставьте готовые платёжные ссылки ЮMoney, PayPal и СБП.' => '对于 [payment]，插入现成的付款链接 YuMoney、PayPal 和 SBP。',
    'Статус оплаты проверяется в кабинете провайдера.' => '付款状态在提供商的帐户中检查。',
    'В HTML и визуальном редакторе значки форматируют текст, добавляют H1–H5 и списки.' => '在 HTML 和可视化编辑器中，图标格式化文本、添加 H1–H5 和列表。',
    'Установите курсор и выберите отдельно шаблон, компонент, изображение или иконку.' => '定位光标并单独选择模板、组件、图像或图标。',
    'Для форм доступны сохранённые коды, а для компонентов — их параметры.' => '保存的代码可用于表单，其参数可用于组件。',
    'Вставка Font Awesome доступна при включённой библиотеке.' => '启用库后，Font Awesome 插入即可使用。',
    'Нажмите имя папки слева, чтобы управлять разделом справа.' => '单击左侧的文件夹名称可管理右侧的部分。',
    'Там можно выбрать родительский раздел, настроить обычное и мобильное меню или указать URL перехода.' => '您可以在其中选择父部分、配置常规菜单和移动菜单，或指定转换 URL。',
    'Пустая страница раздела показывает подразделы.' => '空白部分页面显示小节。',
    'В «Обслуживании» задайте правила вида /contact.html => /contacts/ и редактируйте страницы ошибок в /error/.' => '在“维护”中，设置 /contact.html => /contacts/ 等规则，并在 /error/ 中编辑错误页面。',
    'Поиск и язык на телефоне доступны через иконки в шапке.' => '手机上的搜索和语言可通过标题中的图标进行。',
    'Кнопки в шапке админки · 1.6.4' => '管理标题中的按钮 · 1.6.4',
    'Глобус открывает сайт, стрелка завершает сеанс администратора.' => '地球仪打开站点，箭头结束管理员会话。',
    'На телефоне видны только иконки.' => '手机上仅显示图标。',
    'Подсказки появляются при наведении или фокусе с клавиатуры.' => '当您将鼠标悬停或使用键盘聚焦时，会出现工具提示。',
    '«Содержимое», «Формы и заявки» и «Сайт и сервисы» открываются сразу.' => '“内容”、“表格和应用程序”以及“网站和服务”立即开放。',
    'Под шапкой выбранного раздела доступны его вкладки.' => '其选项卡位于所选部分的标题下。',
    'Вставьте [bread-crumbs] или [search] в HTML главной страницы (index.php) или шаблона.' => '将 [bread-crumbs] 或 [search] 插入主页 (index.php) 或模板的 HTML 中。',
    'Блок появится в указанном месте один раз.' => '该块将在指定位置出现一次。',
    'Галочка хлебных крошек и режим поиска действуют и для вставленных тегов. [privacy] выводит ссылку на /privacy/.' => '面包屑复选框和搜索模式也适用于插入的标签。 [privacy] 显示指向 /privacy/ 的链接。',
    'Текст политики редактируется в разделе «Страницы».' => '政策文本在“页面”部分进行编辑。',
    'Откройте «Шаблоны оформления» для правки главной и страницы /privacy.php.' => '打开“设计模板”编辑主页和/privacy.php页面。',
    'Код [page-content] выводит содержимое главной.' => '代码[page-content]显示主页的内容。',
    'В политике [site-name] и [site-url] берут название и публичный адрес из «Настройки → Основные».' => '在策略 [site-name] 和 [site-url] 中，从“设置→常规”中获取名称和公共地址。',
    'Дополните начальный текст сведениями о вашем сайте и обработке данных.' => '使用有关您的站点和数据处理的信息完成初始文本。',
    'В подвале [conf-policy] даёт ссылку на политику, [cookies] открывает настройки, а [top] прокручивает страницу вверх.' => '在页脚中，[conf-policy] 提供指向策略的链接，[cookies] 打开设置，[top] 滚动到页面顶部。',
    'Аналитика и встроенные карты CMS ждут согласия.' => '分析和内置 CMS 地图正在等待达成协议。',
    'Скрипты, вручную добавленные в шаблоны или служебные заголовки, требуют собственной настройки.' => '手动添加到模板或服务标头的脚本需要自己的配置。',
    'Откройте «Шаблоны оформления → Функции» после вкладки «Служебные заголовки».' => '打开“服务标题”选项卡后的“设计模板→功能”。',
    'Добавляйте замыкания в возвращаемый массив.' => '将闭包添加到返回的数组中。',
    'В PHP-шаблоне вызовите `translit("Москва")` или `ew_call("translit", "München")`.' => '在 PHP 模板中，调用 `translit("Москва")` 或 `ew_call("translit", "München")`。',
    'В HTML вставьте [func=translit value="Москва и München"].' => '在 HTML 中插入 [func=translit value="Москва и München"]。',
    'Пример выдаёт `Moskva i Muenchen`.' => '该示例生成 `Moskva i Muenchen`。',
    'В «Шаблонах оформления» поле уже содержит исходник PHP и HTML с подсветкой.' => '在“设计模板”字段中已经包含突出显示的 PHP 和 HTML 源代码。',
    'При редактировании штатного шаблона выбирается «Свой PHP».' => '编辑标准模板时，选择“自定义 PHP”。',
    'Сохранение создаёт пользовательскую версию.' => '保存会创建自定义版本。',
    'Кнопками рядом с шаблоном можно отменить последнюю правку или восстановить исходник.' => '使用模板旁边的按钮，您可以撤消上次编辑或恢复原始内容。',
    'Редакторы шаблонов оформления, модулей и functions.php проверяют синтаксис командой `php -l`.' => '设计模板、模块和 functions.php 编辑器使用 `php -l` 命令检查语法。',
    'При ошибке остаётся предыдущая версия.' => '如果出现错误，则保留以前的版本。',
    'Для выбора PHP CLI на сервере используется переменная `SITE_PHP_LINT_BINARY`.' => '要选择服务器上的 PHP CLI，请使用变量 `SITE_PHP_LINT_BINARY`。',
    'CodeMirror включён по умолчанию на новой установке.' => '新安装时默认启用 CodeMirror。',
    'Настройка находится в «Библиотеки и шрифты».' => '该设置位于“库和字体”中。',
    'В компактном поиске поле раскрывается влево, крестик очищает строку, а клавиша Enter запускает поиск.' => '在紧凑搜索中，字段向左扩展，十字清除该行，然后按 Enter 键开始搜索。',
    'Меню под шапкой админки и панель правки на сайте показывают иконки с подписями.' => '管理面板标题下的菜单和网站上的编辑面板显示带有标题的图标。',
    'На узком экране остаются иконки.' => '图标保留在窄屏幕上。',
    'Подсказки открываются при наведении и при фокусе с клавиатуры на узком экране. «Скрыть» находится рядом с остальными действиями страницы.' => '悬停时工具提示会打开，键盘会聚焦在窄屏幕上。 “隐藏”位于其余页面操作旁边。',
    'Переключатель «Режим правки» расположен справа.' => '编辑模式开关位于右侧。',
    'В «PHP-модулях» краткое описание предназначено для обычного текста.' => '在“PHP 模块”中，简短描述适用于纯文本。',
    'Вставляйте тело функции в отдельное поле «Исходный код · PHP».' => '将函数主体粘贴到单独的字段“源代码·PHP”中。',
    'В региональных настройках включите нужные языки.' => '在区域设置中，启用所需的语言。',
    'Меню выбора языка в шапке меняет интерфейс и справку, сохраняя текущий раздел.' => '标题中的语言选择菜单会更改界面和帮助，同时保留当前部分。',
    'Тексты страниц и значения ваших настроек хранятся в исходном виде.' => '页面文本和您的设置值以其原始形式存储。',
    'Код [author] выводит подпись Eurowebcart CMS Lite, имя автора Бандалетов Павел и ссылку на GitHub.' => '代码 [author] 显示签名 Eurowebcart CMS Lite、作者姓名 Бандалетов Павел 以及 GitHub 的链接。',
    'Чтобы выбрать место подписи в собственном HTML подвала, вставьте [author] в нужную строку.' => '要选择在自定义 HTML 页脚中放置签名的位置，请将 [author] 粘贴到相应的行中。',
    'Наведите указатель на ссылку «Править компонент» или установите на неё фокус с клавиатуры.' => '将鼠标悬停在“编辑组件”链接上或将键盘焦点设置到它。',
    'Рамка выделит вывод именно этой вставки.' => '该框架将突出显示该特定插入的输出。',
    'В «Настройки → Основные» выберите вид поиска.' => '在“设置→常规”中选择搜索类型。',
    'В «Обслуживании» можно переиндексировать страницы, а поле в шапке админки ищет по настройкам.' => '在“维护”中，您可以重新索引页面，管理标题中的字段可以按设置搜索。',
    'Поиск выводит по 20 пронумерованных результатов на страницу.' => '搜索每页显示 20 个编号结果。',
    'Компактная строка раскрывается влево от лупы, а значок Enter расположен внутри поля.' => '紧凑的线条扩展到放大镜的左侧，并且 Enter 图标位于该字段内。',
    'Поиск в шапке админки предлагает прямые ссылки на настройки.' => '管理标题中的搜索提供了指向设置的直接链接。',
    'В «Настройки → Основные» выберите вид поиска: выключен, компактный с лупой или расширенный.' => '在“设置 → 常规”中选择搜索类型：关闭、带放大镜的紧凑型或扩展型。',
    'Поле поиска в шапке админки ведёт к нужным настройкам.' => '管理标题中的搜索字段可引导至所需的设置。',
    'Индекс обновляется после правок в админке и может перестраиваться по расписанию для изменений по FTP.' => '在管理面板中进行编辑后，索引会更新，并且可以通过 FTP 按计划重建索引。',
    'В индекс входят текст страниц, вложенные страницы и инфоблоки; произвольный PHP при индексации пропускается.' => '索引包括页面文本、子页面和信息块；索引过程中会跳过任意​​ PHP。',
    'Раскройте модуль для просмотра настроек и списка страниц с его вставкой.' => '展开模块以查看设置和包含其插入的页面列表。',
    'Через «Создать модуль» добавьте имя, имя файла и тело функции PHP.' => '通过“创建模块”添加 PHP 函数的名称、文件名和主体。',
    'Возвращаемая строка вставляется кодом [php]имя[/php].' => '返回的行插入代码为 [php]name[/php]。',
    'При переименовании файла код вставки сохраняется. CodeMirror включается в разделе библиотек.' => '重命名文件时，嵌入代码将被保存。 CodeMirror 包含在库部分中。',
    'Можно отменить до восьми изменений каждого шаблона и вернуть исходный PHP для общих настроек и каждого домена.' => '对于每个模板，您最多可以撤消八次更改，并将常规设置和每个域恢复为原始 PHP。',
    'Чтобы изменить HTML, выберите «Свой HTML».' => '要更改 HTML，请选择自定义 HTML。',
    'Пользовательские PHP-шаблоны размещайте в templates/local/.' => '将自定义 PHP 模板放置在 templates/local/. 中',
    'Переключатель языков виден даже при создании перевода, а сохранённые переводы перемещаются вместе со страницей.' => '即使在创建翻译时，语言切换器也是可见的，并且保存的翻译会随页面移动。',
    'В настройках CAPTCHA, карт, телефонии и аналитики есть ссылки на кабинеты и инструкции провайдеров. URL HTTP API обратного звонка и токен можно задать в админке.' => '在验证码、地图、电话和分析设置中，有指向提供商办公室和说明的链接。回调 HTTP API URL 和令牌可以在管理面板中设置。',
    'Подшаблоны зарегистрированного поддомена сохраняются при переходе на основной домен.' => '当移动到主域时，已注册子域的子模板将被保留。',
    'Планировщик хостинга должен запускать php update.php --scheduled каждые 15 минут.' => '托管调度程序应每 15 分钟运行一次 php update.php --scheduled。',
    'В разделе «Обслуживание» перестройте текстовый индекс после публикации или изменения страниц в админке или по FTP.' => '在“维护”部分中，在管理区域或通过 FTP 发布或更改页面后重建文本索引。',
    'Поиск показывает подсказки по открытым страницам и учитывает язык посетителя.' => '搜索会显示打开页面的建议，并考虑访问者的语言。',
    'Кеш разобранного контента выключен по умолчанию.' => '默认情况下禁用已解析内容缓存。',
    'Включайте и очищайте его там же.' => '打开它并在那里清洁它。',
    'Сессионные формы и динамические блоки обрабатываются при каждом запросе.' => '会话表单和动态块根据每个请求进行处理。',
    'После входа над шапкой появится панель правки.' => '登录后，标题上方将出现一个编辑面板。',
    'Справа можно включить или выключить режим для всего сайта.' => '在右侧，您可以打开或关闭整个站点的模式。',
    'Включите его, чтобы править параметры возле вставок. CSS и JS текущей страницы открываются в лайтбоксе.' => '打开它可以编辑插入旁边的参数。当前页面的 CSS 和 JS 在灯箱中打开。',
    'В админке доступны HTML и визуальный редактор, вставка кодов и AJAX-управление папками галерей и файлов с массовой загрузкой и сортировкой.' => '管理面板中提供 HTML 和可视化编辑器、代码插入以及画廊和文件夹的 AJAX 管理以及批量加载和排序功能。',
    'Без параметров галерея, карусель и файлы используют общие настройки.' => '如果没有参数，图库、轮播和文件将使用相同的设置。',
    'Значения во вставке переопределяют только заданные параметры. width принимает 100, 50, 33 и 25 в процентах, допускается знак %.' => '插入中的值仅覆盖指定的设置。 width 接受 100%、50%、33% 和 25%，允许使用 % 符号。',
    'На телефоне блоки складываются в одну колонку. numbers=off убирает номер слайда, стрелки и свайпы остаются.' => '在手机上，这些块堆叠成一列。 Numbers=off 删除幻灯片编号，保留箭头和滑动。',
    'Мобильное меню выезжает справа.' => '移动菜单在右侧滑出。',
    'Хлебные крошки можно выключить в разделе «Настройки → Основные».' => '可以在“设置”→“常规”中关闭面包屑导航。',
    'В региональных настройках выберите языки сайта и админки, валюту, форматы чисел, даты, времени и часовой пояс. index_en.php рядом с index.php задаёт перевод; без отдельного файла старый адрес откроет основной текст.' => '在区域设置中，选择网站和管理面板的语言、货币、数字格式、日期、时间和时区。 index.php 旁边的 index_en.php 指定翻译；如果没有单独的文件，旧地址将打开正文。',
    'Тип «Цена» в инфоблоке использует выбранную валюту. «Тема и цвета» показывает цвета сохранённых тем и меняет режим сразу.' => '信息块中的“价格”类型使用所选货币。 “主题和颜色”显示已保存主题的颜色并立即更改模式。',
    'Загрузите отдельные логотипы для светлой и тёмной темы.' => '上传浅色和深色主题的单独徽标。',
    'Для Roboto Condensed и других шрифтов можно менять фразу предпросмотра.' => '对于 Roboto Condensed 和其他字体，您可以更改预览短语。',
    '«Настройки → CAPTCHA» задаёт общие ключи Google reCAPTCHA v2 и включает защиту для всех обычных форм.' => '“设置 → CAPTCHA”设置 Google reCAPTCHA v2 公钥并启用对所有常规表单的保护。',
    'Параметры отдельных форм остаются доступны в «Формах».' => '表格中仍然提供单个表格的选项。',
    'Сообщения и обратные звонки идут по 20 на страницу, непрочитанные вверху.' => '每页有 20 条消息和回调，未读位于顶部。',
    'В «Интеграциях» настраиваются Zadarma, Telegram, аналитика и карты Google или Яндекса.' => '在“集成”中，配置了 Zadarma、Telegram、分析和 Google 或 Yandex 地图。',
    'Точки со страницы группируются на одной карте, кластеризацию можно выключить.' => '页面中的点被分组在一张地图上；可以关闭集群。',
    'В библиотечном лайтбоксе проверяется активная версия и доступен код вставки. CodeMirror включается отдельно и поддерживает «Авто», HTML, CSS, JS, PHP и RAW.' => '库灯箱检查活动版本并使嵌入代码可用。 CodeMirror 单独包含，支持 Auto、HTML、CSS、JS、PHP 和 RAW。',
    'В разделе «PHP-модули» настройте название, описание и доступность проверенного модуля.' => '在“PHP Modules”部分，配置测试模块的名称、描述和可用性。',
    'В редакторе выберите его код вставки.' => '在编辑器中，选择其嵌入代码。',
    'Тестовый server-date показывает дату с региональным форматом.' => '测试服务器日期以区域格式显示日期。',
    'Исполняемый код модулей хранится в защищённом каталоге и добавляется через файловый доступ разработчика.' => '模块的可执行代码存储在受保护的目录中，并通过开发人员的文件访问添加。',
    'Настройки страницы · 1.6.8' => '页面设置·1.6.8',
    'Пишите содержимое в «Правке».' => '在“编辑”中写入内容。',
    'Адрес, меню и расписание публикации настраиваются в «Настройках страницы».' => '地址、菜单和发布时间表在“页面设置”中配置。',
    'Заголовки, метаописание, ключевые слова и включение в sitemap находятся в SEO.' => '标题、元描述、关键字和站点地图包含在 SEO 中。',
    'Координаты и примеры тегов находятся в «Картах».' => '坐标和示例标签可以在地图中找到。',
    'Пустые даты снимают ограничения.' => '空白日期消除了限制。',
    'Используется часовой пояс сайта.' => '使用该网站的时区。',
    'Скрытую страницу нужно отдельно опубликовать.' => '隐藏页面必须单独发布。',
    '`[map]` — карта с точкой текущей страницы.' => '`[map]` - 当前页面上有一个点的地图。',
    '`[maps]` — карта со всеми точками опубликованных страниц.' => '`[maps]` - 包含已发布页面的所有点的地图。',
    'Баннеры и редактор изображений · 1.6.8' => '横幅和图像编辑器·1.6.8',
    'Настройте наборы и кадры в «Компонентах».' => '在组件中设置集和框架。',
    'Можно взять фотографии из папки, задать подпись, кнопку со ссылкой, форму или обратный звонок, и выбрать время показа.' => '您可以从文件夹中拍摄照片，设置标题、带有链接的按钮、表单或回调，并选择显示时间。',
    'В режиме правки кнопки кадра открывают его настройки.' => '在编辑模式下，框架按钮可打开其设置。',
    'Вставка изображения открывает папки, загрузку, удаление и создание копии с поворотом или изменённым размером.' => '插入图像会打开文件夹、下载、删除并创建旋转或调整大小的副本。',
    'Для создания копии нужен GD.' => '要创建副本，您需要 GD。',
    'Выбор Font Awesome показывает значки и поддерживает поиск по имени.' => 'Font Awesome 选择显示图标并支持按名称搜索。',
    'Языки · 1.6.9' => '语言1.6.9',
    'Для нового раздела выберите нужный уровень.' => '对于新部分，选择所需的级别。',
    'Подраздел создаётся внутри открытого раздела, соседний — рядом с ним, корневой — на верхнем уровне сайта.' => '在开放部分内创建子部分，在其旁边创建相邻部分，并在站点的顶层创建根部分。',
    'Совместимость PHP и навигация · 1.6.10' => 'PHP 兼容性和导航·1.6.10',
    'Минимальная версия PHP — 7.2.' => '最低 PHP 版本为 7.2。',
    'Сайт и админка поддерживают PHP 8.6.' => '该网站和管理面板支持 PHP 8.6。',
    'Для своих PHP-модулей и шаблонов используйте синтаксис версии, установленной на сервере.' => '对于您的 PHP 模块和模板，请使用服务器上安装的版本的语法。',
    'Корзина удаляет строку из редактора инфоблока.' => '回收站从信息块编辑器中删除该行。',
    'Удаление столбца убирает все значения этого столбца.' => '删除列会删除该列的所有值。',
    'Правки записываются при сохранении инфоблока, в том числе при автосохранении после перетаскивания.' => '保存信息块时会记录编辑，包括拖动后自动保存时。',
    'ZIP хранится в закрытой папке и включает страницы, медиа, инфоблоки, настройки, свои шаблоны и PHP-модули.' => 'ZIP 存储在一个封闭的文件夹中，包括页面、媒体、信息块、设置、自定义模板和 PHP 模块。',
    'Учётная запись администратора и входящие заявки сохраняются отдельно.' => '管理员帐户和传入请求单独保存。',
    'Для архивации нужно расширение PHP Zip.' => '为了存档，您需要 PHP Zip 扩展。',
    'Заменить содержимое и настройки выбранной копией.' => '将内容和设置替换为所选副本。',
    'Перед заменой будет создан новый бэкап текущего состояния.' => '在替换之前，将创建当前状态的新备份。',
    'Сканирование ищет медиа без ссылок в сохранённом содержимом.' => '扫描会查找存储内容中没有链接的媒体。',
    'Проверьте список и отметьте нужные файлы.' => '检查列表并标记您需要的文件。',
    'Перед очисткой создаётся резервная копия.' => '清理之前会创建备份。',
    'Удаление кода компонента оставляет его папку и файлы на месте.' => '删除组件的代码会保留其文件夹和文件。',
    'В кабинете Яндекс Карт создайте ключ для продукта «JavaScript API» в разделе «Карты».' => '在您的 Yandex 地图帐户中，为“地图”部分中的“JavaScript API”产品创建密钥。',
    'Ограничьте ключ доменом по HTTP Referer.' => '将密钥限制为 HTTP Referer 域。',
    'При включённом провайдере на вкладке «Карты» страницы нажмите «Выбрать на карте», поставьте точку и перенесите её координаты в поля.' => '打开提供程序后，在页面的“地图”选项卡上，单击“在地图上选择”，放置一个点并将其坐标传输到字段。',
    'В визуальном редакторе выделите текст для выравнивания или снятия форматирования.' => '在可视化编辑器中，选择要对齐或删除格式的文本。',
    'Нажмите на изображение, чтобы открыть его параметры.' => '单击图像打开其选项。',
    'Потяните за угол для изменения размера или перетащите само изображение в другое место.' => '拖动一个角来调整大小或将图像本身拖动到另一个位置。',
    'Для ссылки доступны URL, email, телефон и якорь.' => '该链接提供 URL、电子邮件、电话和锚点。',
    'Кнопка может открыть URL, форму, обратный звонок или оплату.' => '该按钮可以打开 URL、表单、回调或付款。',
    'Для оплаты используйте ссылку провайдера на указанную сумму.' => '要付款，请使用提供商的链接支付指定金额。',
    'Режимы HTML и «Визуальный редактор» переключаются вкладками. SUP, SUB и «Параграф» вставляют соответствующие элементы.' => 'HTML 和可视化编辑器模式通过选项卡切换。 SUP、SUB 和段落插入适当的元素。',
    'Коды видны рядом с названиями компонентов.' => '这些代码在组件名称旁边可见。',
    'Папки медиа создаются при вставке, если пути содержат только латинские буквы, цифры, дефисы и подчёркивания в сегментах.' => '如果路径中的段仅包含拉丁字母、数字、连字符和下划线，则在插入时创建媒体文件夹。',
    'Вкладка «Языки» ведёт к выбору дополнительных языков сайта.' => '“语言”选项卡可以选择其他站点语言。',
    'Автор — Бандалетов Павел. [Исходный проект и обновления](https://github.com/bandaletov72/ewc-lite).' => '作者 - Бандалетов Павел。 [原始项目和更新](https://github.com/bandaletov72/ewc-lite)。',
    '[FAQ по админке](faq.md) доступен также во вкладке «Помощь».' => '[管理员常见问题解答](faq.md) 也可在“帮助”选项卡中找到。',
    '[Справка по актуальной версии на десяти языках](../README.md) описывает поиск, правку на сайте, локализацию и обслуживание. [Admin FAQ in English](../en/faq.md).' => '[当前版本的十种语言帮助 ](../README.md) 描述了搜索、网站编辑、本地化和维护。 [英文版管理员常见问题解答](../en/faq.md)。',
    'Для планового обслуживания добавьте команду `php update.php --scheduled` в планировщик хостинга с периодом 15 минут.' => '对于定期维护，请将命令 `php update.php --scheduled` 添加到托管调度程序，周期为 15 分钟。',
    'В разделе «Обслуживание» можно независимо включить переиндексацию и установить интервал проверки подписанных обновлений GitHub.' => '在维护部分，您可以独立启用重新索引并设置签名 GitHub 更新的检查间隔。',
    'Локальный запуск' => '本地发布',
    'Перейдите в каталог `php-site` и запустите встроенный сервер PHP.' => '转到 `php-site` 目录并启动内置 PHP 服务器。',
    'Сайт откроется по адресу `http://127.0.0.1:8000/`, админка находится по адресу `http://127.0.0.1:8000/admin/`.' => '该网站将在地址 `http://127.0.0.1:8000/` 上打开，管理面板位于 `http://127.0.0.1:8000/admin/`。',
    'Установка и первый вход' => '安装和首次登录',
    'На локальном сервере откройте `/admin/` и создайте учётную запись.' => '在本地服务器上，打开 `/admin/` 并创建一个帐户。',
    'На втором шаге задайте название сайта, метаописание, текст подвала, палитру и режим темы.' => '第二步，设置站点名称、元描述、页脚文本、调色板和主题模式。',
    'Логотип можно загрузить сразу при наличии PHP GD.' => '如果您有 PHP GD，则可以立即下载徽标。',
    'Мастер создаст из него favicon.' => '向导将从中创建一个网站图标。',
    'Нажмите «Сохранить и открыть админку» или продолжите с текущими настройками.' => '单击“保存并打开管理”或继续当前设置。',
    'Если выйти из мастера, он продолжится при следующем входе.' => '如果您退出向导，它将在您下次登录时继续。',
    'На хостинге выполните из каталога проекта `php admin/setup.php` и введите одноразовый код на первом шаге мастера.' => '在主机上，从项目目录运行 `php admin/setup.php` 并在向导的第一步中输入一次性代码。',
    'Код погашается при создании учётной записи.' => '当您创建帐户时，将兑换该代码。',
    'Повторный запуск команды до установки заменяет предыдущий код.' => '安装前再次运行该命令将替换之前的代码。',
    'Установка обновления сохраняет прежнюю учётную запись и настройки.' => '安装更新会保留以前的帐户和设置。',
    'Если версия до обновления использовала `SITE_ADMIN_PASSWORD_HASH`, вход сохраняется с логином `admin` и прежним паролем.' => '如果更新之前的版本使用`SITE_ADMIN_PASSWORD_HASH`，则使用登录名`admin`和之前的密码保存登录。',
    'Для работы приложения нужны PHP-сессии и права записи в `admin/`, `admin/write-lock.php`, `admin/inbox/`, `data/` и каталоги редактируемых страниц.' => '为了使应用程序正常工作，您需要 PHP 会话以及对 `admin/`、`admin/write-lock.php`、`admin/inbox/`、`data/` 和可编辑页面目录的写入权限。',
    'Чтобы создавать страницы и каталоги в корне, дайте процессу PHP право записи в корень проекта.' => '要在根目录创建页面和目录，请授予 PHP 进程对项目根目录的写入权限。',
    'Используйте веб-сервер с HTTPS, обработкой `.php` и `index.php` в списке индексных файлов.' => '使用带有 HTTPS 的 Web 服务器，处理索引文件列表中的 `.php` 和 `index.php`。',
    'Отключите листинг каталогов.' => '禁用目录列表。',
    'При HTTPS за обратным прокси передайте PHP признак `HTTPS` через доверенную конфигурацию сервера.' => '对于反向代理后面的 HTTPS，请通过可信服务器配置将 `HTTPS` 属性传递给 PHP。',
    'В админке главная указана как `/`, остальные страницы в папках — как `/contacts/`.' => '在管理面板中，主页列为 `/`，文件夹中的其余页面列为 `/contacts/`。',
    'Для создания вложенной страницы укажите, например, `/Services-1/Repair/`.' => '例如，要创建子页面，请输入 `/Services-1/Repair/`。',
    'Админка сама создаст каталоги и `index.php`.' => '管理面板将创建目录和 `index.php` 本身。',
    'Для отдельного файла укажите адрес вида `/Services-1/About_2.php`.' => '对于单独的文件，请输入类似 `/Services-1/About_2.php` 的地址。',
    'В именах файлов и папок разрешены `A–Z`, `a–z`, `0–9`, дефис и подчёркивание.' => '文件和文件夹名称中允许使用 `A–Z`、`a–z`、`0–9`、连字符和下划线。',
    'Имена вводятся без пробелов.' => '输入的名称不带空格。',
    'В корне разрешена только главная страница.' => '在根目录下，只允许使用主页。',
    'Служебные каталоги, включая `data`, `admin`, `templates`, `css` и `js`, зарезервированы.' => '保留`data`、`admin`、`templates`、`css`、`js`等服务目录。',
    'В списке страниц папки можно раскрыть.' => '在页面列表中，可以展开文件夹。',
    'Галочка «В меню», скрытие, публикация и удаление сохраняются через AJAX.' => '在菜单复选框中，隐藏、发布和删除都是通过 AJAX 保存的。',
    'Скрытие, публикация и удаление требуют подтверждения.' => '隐藏、发布、删除都需要确认。',
    'Перетаскивайте за значок ⠿ для сортировки соседних страниц.' => '拖动 ⠿ 图标对相邻页面进行排序。',
    'Скрытая страница перестаёт открываться и исчезает из меню до публикации.' => '隐藏页面在发布前停止打开并从菜单中消失。',
    'В редакторе страницы откройте блок «Переместить страницу» и укажите папку назначения.' => '在页面编辑器中，打开“移动页面”块并指定目标文件夹。',
    'Например, при переносе `/contacts/` в `/company/` новый адрес будет `/company/contacts/`.' => '例如，如果您将 `/contacts/` 转账至 `/company/`，则新地址将为 `/company/contacts/`。',
    'Вложенные страницы остаются по прежним адресам.' => '嵌套页面保留在相同的地址。',
    'Обновите собственные ссылки и коды `[include]`, ведущие на перенесённую страницу.' => '更新您自己的链接和指向迁移页面的 `[include]` 代码。',
    'Перетащите за значок ⠿, чтобы изменить порядок на одном уровне.' => '拖动⠿图标可更改同一级别内的顺序。',
    'Для одной страницы откройте «Переместить страницу» в её настройках.' => '对于一页，在其设置中打开“移动页面”。',
    'Значок рядом с папкой открывает выбор родительского раздела.' => '文件夹旁边的图标可打开父部分的选择。',
    'Выберите другой раздел или корневую папку и нажмите «Переместить папку».' => '选择不同的分区或根文件夹，然后单击移动文件夹。',
    'Папка переносится со всеми вложенными страницами и файлами.' => '该文件夹与所有附加的页面和文件一起传输。',
    'Проверьте ссылки и [include], указывавшие на старые адреса.' => '检查指向旧地址的链接和 [include]。',
    'Контент можно править в текстовом редакторе и добавлять через FTP или SFTP.' => '可以在文本编辑器中编辑内容并通过 FTP 或 SFTP 添加内容。',
    'Файл должен быть в UTF-8 без BOM.' => '文件必须采用 UTF-8 无 BOM 格式。',
    'Сохраните служебный PHP-блок до строки `__halt_compiler();`.' => '将 PHP 服务块保存到 `__halt_compiler();` 行。',
    'В файле новой страницы вставьте этот блок из примера нужной глубины и проверьте относительный путь к корневому `index.php`.' => '在新页面文件中，在所需深度插入示例中的此块，并检查根 `index.php` 的相对路径。',
    'Следом идут заголовки, одна пустая строка и HTML-фрагмент страницы.' => '接下来是标题、一个空行和页面的 HTML 片段。',
    'Обязателен `Title`.' => '`Title` 为必填项。',
    'Пустой `Heading` берётся из `Title`. `Description` заполняет метаописание страницы. `MenuVisible: 1` показывает ссылку в меню, `MenuVisible: 0` скрывает её.' => '空的 `Heading` 取自 `Title`。 `Description`填写页面的元描述。 `MenuVisible: 1` 在菜单中显示链接，`MenuVisible: 0` 隐藏它。',
    'Для `index.php` папки отключение галочки также скрывает из меню все вложенные страницы.' => '对于 `index.php` 文件夹，取消选中该复选框也会隐藏菜单中的所有子页面。',
    'Если `MenuVisible` отсутствует, галочка наследует прежнее правило и считается включённой при заполненном `Menu`.' => '如果缺少 `MenuVisible`，则该复选框将继承之前的规则，并在填写 `Menu` 时被视为已启用。',
    'При включённой галочке пустое поле `Menu` заменяется заголовком `Title`. `Order` задаёт последовательность в пределах одного уровня и по умолчанию равен 100.' => '启用该复选框后，空字段 `Menu` 将替换为标头 `Title`。 `Order` 指定一级内的顺序，默认为 100。',
    'Вкладка «CSS и JS» хранит общий CSS и JavaScript для публичных страниц.' => 'CSS 和 JS 选项卡存储公共页面的常用 CSS 和 JavaScript。',
    'В редакторе страницы есть отдельный блок «CSS и JavaScript страницы».' => '页面编辑器有一个单独的块“CSS 和 JavaScript 页面”。',
    'Код страницы загружается после общего.' => '页面代码是在通用代码之后加载的。',
    'Указывайте только содержимое файлов, без тегов `<style>` и `<script>`.' => '仅指定文件的内容，不指定 `<style>` 和 `<script>` 标签。',
    'Допустимый размер каждого поля — до 64 КиБ.' => '每个字段允许的大小最大为 64 KiB。',
    'Для ссылок на изображения из CSS можно использовать пути от корня сайта.' => '要从 CSS 链接到图像，您可以使用站点根目录中的路径。',
    'Вкладка «Помощь» содержит примеры доступных шаблонов и компонентов.' => '“帮助”选项卡包含可用模板和组件的示例。',
    'В разделе «Шаблоны оформления» можно просмотреть исходники `header.php`, `footer.php`, `menu.php` и `mobile-menu.php` и задать для каждого общий HTML. «Служебные заголовки» вставляют общие метатеги, коды счётчиков и скрипты в `<head>` или перед `</body>`.' => '在“设计模板”部分，您可以查看 `header.php`、`footer.php`、`menu.php` 和 `mobile-menu.php` 的源，并为每个模板设置通用 HTML。 “服务标头”将通用元标记、计数器代码和脚本插入 `<head>` 或 `</body>` 之前。',
    'На каждой опубликованной полной странице `rel="canonical"` формируется из её обычного адреса без параметров запроса.' => '在每个发布的完整页面上，`rel="canonical"` 都是由其常规地址形成的，不带查询参数。',
    'Настройки, подшаблоны и домены' => '设置、子模板和域',
    'В разделе «Настройки» задаются название сайта, метаописание по умолчанию, текст подвала и переменные.' => '在“设置”部分，您可以设置站点名称、默认元描述、页脚文本和变量。',
    'В тексте подвала `[year]` автоматически выводит текущий год.' => '在页脚文本中，`[year]` 自动显示当前年份。',
    'Переменные записываются по одной на строку, например `[city] = Москва` и `[spb] = Санкт-Петербург`.' => '每行写入一个变量，例如 `[city] = Москва` 和 `[spb] = Санкт-Петербург`。',
    'Чтобы вывести значение в названии сайта, содержимом страницы, заголовке или подвале, вставьте `[city]`.' => '要在网站标题、页面内容、页眉或页脚中显示值，请插入 `[city]`。',
    'В PHP-шаблонах можно использовать `site_escape($settings[\'variables\'][\'city\'] ?? \'\')`.' => '在 PHP 模板中，您可以使用 `site_escape($settings[\'variables\'][\'city\'] ?? \'\')`。',
    'Системные подстановки включают `[year]`, `[month]`, `[day]`, `[time]` (часы и минуты), `[dmY]` и `[date]` (дата ДД.ММ.ГГГГ), `[datetime]` (дата и время).' => '系统替换包括 `[year]`、`[month]`、`[day]`、`[time]`（小时和分钟）、`[dmY]` 和 `[date]`（日期 DD.MM.YYYY）、`[datetime]`（日期和时间）。',
    'Используется часовой пояс PHP.' => '使用 PHP 时区。',
    'В «Основные → Логотипы и иконки сайта» можно загрузить PNG, JPEG, GIF или WebP.' => '在“基本 → 站点徽标和图标”中，您可以上传 PNG、JPEG、GIF 或 WebP。',
    'Загрузки обрабатывает PHP GD.' => '下载由 PHP GD 处理。',
    'Кнопка создания favicon делает прозрачный PNG 64 × 64 из выбранного или сохранённого логотипа.' => '创建图标按钮可以根据所选或保存的徽标创建透明的 64×64 PNG。',
    'Изображения хранятся в `templates/images/branding/` и `templates/icons/branding/`.' => '图像存储在`templates/images/branding/` 和`templates/icons/branding/` 中。',
    '«Подшаблоны» хранит имя, описание и значение каждого кода.' => '“子模板”存储每个代码的名称、描述和含义。',
    'Для телефона создайте `[tel]`.' => '对于电话，创建 `[tel]`。',
    'Чтобы задать заголовок вкладки через подшаблон, создайте `[title]` и укажите его в поле `Title` страницы.' => '要通过子模板设置选项卡标题，请创建 `[title]` 并在页面上的 `Title` 字段中指定它。',
    'После заголовка вкладки выводится название сайта.' => '选项卡标题后显示站点的名称。',
    'Подстановки работают в тексте страницы и текстовых метаданных.' => '替换适用于页面文本和文本元数据。',
    'Для ссылки вставьте весь тег `<a>` как значение подшаблона и разместите код в тексте между тегами.' => '对于链接，插入整个 `<a>` 标记作为子模板值，并将代码放置在标记之间的文本中。',
    'В метаданных HTML из значения преобразуется в текст.' => '在元数据中，HTML 从值转换为文本。',
    'Добавляйте поддомены в разделе «Домены».' => '在“域”部分添加子域。',
    'В одноимённой админке поддомена выберите «Текущий домен», либо откройте нужный домен из общего списка.' => '在同名子域的管理面板中，选择“当前域”，或从常规列表中打开所需的域。',
    'Локальное значение имеет приоритет над общим.' => '局部含义优先于一般含义。',
    'Публичная страница выбирает значения по домену в своём адресе, а внутренние ссылки сохраняют его.' => '公共页面在其地址中按域选择值，内部链接保存它。',
    'Для подключения поддомена настройте DNS и веб-сервер на хостинге, чтобы домен обслуживал тот же каталог проекта.' => '要连接子域，请在您的主机上配置 DNS 和 Web 服务器，以便该域提供相同的项目目录。',
    'Кнопка «Шаблоны» рядом с доменом открывает редактор `[header]`, `[mobile-menu]`, `[menu]` и `[footer]`.' => '域旁边的“模板”按钮可打开 `[header]`、`[mobile-menu]`、`[menu]` 和 `[footer]` 编辑器。',
    'Для каждого блока можно задать свой HTML или использовать общую версию.' => '对于每个块，您可以设置自己的 HTML 或使用通用版本。',
    'Общие шаблоны настраиваются в том же разделе.' => '通用模板在同一部分中配置。',
    'Компоненты в HTML' => 'HTML 中的组件',
    '| Код | Результат |' => '|代码|结果 |',
    '| `[gal]/images/myfotos/[/gal]` | Карусель фотографий с плавной прокруткой, стрелками и свайпом |' => '| `[gal]/images/myfotos/[/gal]` |具有平滑滚动、箭头和滑动功能的照片轮播 |',
    '| `[fotos]/images/myfotos/[/fotos]` | Фотогалерея со ссылками на оригиналы |' => '| `[fotos]/images/myfotos/[/fotos]` |照片库，附有原件链接 |',
    '| `[files]/files/myfiles[/files]` | Список файлов с иконками по расширению |' => '| `[files]/files/myfiles[/files]` |带有扩展名的图标的文件列表 |',
    '| `[include]/contacts/[/include]` | HTML другой страницы с её подшаблонами и компонентами |' => '| `[include]/contacts/[/include]` |另一个页面的 HTML 及其子模板和组件 |',
    '| `[form1]` | Форма, настроенная в разделе «Формы» |' => '| `[form1]` |在“表单”部分配置的表单|',
    '| `[callback=Вызвать мастера]` | Кнопка и форма запроса обратного звонка |' => '| `[callback=Вызвать мастера]` |回电请求按钮和表格|',
    '| `[iblock=table]/data/myiblock.txt[iblock]` | Таблица инфоблока |' => '| `[iblock=table]/data/myiblock.txt[iblock]` |信息块表|',
    '| `[iblock=phones]/data/myiblock.txt[iblock]` | Список телефонов инфоблока |' => '| `[iblock=phones]/data/myiblock.txt[iblock]` |信息块电话列表|',
    '| `[phones]`, `[contacts]` | Телефоны или весь настроенный блок контактов |' => '| `[phones]`、`[contacts]` |电话或整个定制的接触块|',
    '| `[soc-icons]` | Иконки всех соцсетей с настроенными ссылками |' => '| `[soc-icons]` |具有自定义链接的所有社交网络的图标|',
    '| `[tg]`, `[vk]`, `[whatsapp]`, `[youtube]`, `[instagram]`, `[max]` | Ссылка на соцсеть с иконкой и подписью |' => '| `[tg]`、`[vk]`、`[whatsapp]`、`[youtube]`、`[instagram]`、`[max]` |带有图标和签名的社交网络链接 |',
    'Поместите фотографии в `templates/images/myfotos/` или `images/myfotos/`.' => '将照片放入 `templates/images/myfotos/` 或 `images/myfotos/`。',
    'Список файлов показывает `zip`, `pdf`, `xls`, `xlsx`, `doc`, `docx`, `png`, `gif`, `jpg`, `jpeg`, `mp4`, `mov` и `mp3`.' => '文件列表显示 `zip`、`pdf`、`xls`、`xlsx`、`doc`、`docx`、`png`、`gif`、`jpg`、`jpeg`、`mp4`、 `mov` 和 `mp3`。',
    'Для `[include]` поддерживается до десяти уровней вложенности.' => '对于 `[include]`，最多支持十层嵌套。',
    'Повтор страницы в текущей цепочке пропускается.' => '跳过当前线程中的页面重复。',
    'Коды компонентов размещайте в теле страницы, отдельной строкой между HTML-блоками.' => '将组件代码放置在页面正文中，位于 HTML 块之间的单独一行上。',
    'В «Настройки → Контакты и соцсети» задайте ссылки, номера, подписи и заголовок блока.' => '在“设置→联系人和社交网络”中设置链接、号码、签名和块标题。',
    'В «Настройки → Тема и цвета» доступны системный, тёмный и светлый режимы и отдельные палитры.' => '在“设置→主题和颜色”中，可以使用系统、深色和浅色模式以及个人调色板。',
    'В «Настройки → Компоненты» задаются общие параметры карусели и фотогалереи.' => '在“设置→组件”中，您可以设置轮播和照片库的常规参数。',
    'Под настройками есть примеры вставки с выбранными значениями.' => '在设置下有插入选定值的示例。',
    'Параметры в коде страницы переопределяют общие значения.' => '页面代码中的参数会覆盖通用值。',
    'В «Тема и цвета» можно сохранить копию выбранных настроек под своим названием или оставить автоматическое название. «Применить» меняет текущее оформление. «Использовать по умолчанию» применяет сохранённую тему и запоминает её для команды «Вернуть тему по умолчанию».' => '在“主题和颜色”中，您可以将所选设置的副本保存在您自己的名称下或保留自动名称。 “应用”更改当前设计。使用默认值应用保存的主题并记住它以用于将主题重置为默认值命令。',
    'Удаление из списка сохраняет текущее оформление сайта.' => '从列表中删除会保留站点的当前设计。',
    'У `[fotos]` число колонок можно задать вручную для широкого экрана или оставить автоматический подбор.' => '对于 `[fotos]`，可以手动设置宽屏幕的列数或自动选择。',
    'На узких экранах сетка сокращает число колонок.' => '在窄屏幕上，网格会减少列数。',
    'Доступны пропорции 4:3, 1:1, 16:9 и исходные, режимы `cover` и `contain`, подписи из имён файлов и ссылки на оригиналы.' => '可用的宽高比为 4:3、1:1、16:9 和原始、`cover` 和 `contain` 模式、文件名签名以及原始链接。',
    'Формы и антиспам' => '表单和反垃圾邮件',
    'В разделе «Формы» можно редактировать `[form1]`, создавать `[form2]` и следующие формы.' => '在“表单”部分，您可以编辑`[form1]`，创建`[form2]`和以下表单。',
    'Для формы задаются адрес получателя, подпись кнопки и поля.' => '对于表单，指定了收件人的地址、按钮签名和字段。',
    'У поля можно указать максимальную длину.' => '该字段可以有最大长度。',
    'Пустое значение использует предел по умолчанию для типа поля.' => '空值使用字段类型的默认限制。',
    'При вводе `89031234567` поле телефона форматирует его как `+7(903)123-45-67`.' => '当您输入 `89031234567` 时，电话字段将其格式设置为 `+7(903)123-45-67`。',
    'Сервер проверяет длину, тип, допустимые варианты выбора и ограничивает суммарный размер запроса.' => '服务器检查长度、类型、有效选择，并限制请求的总大小。',
    'Поля свободного ввода принимают обычный текст. HTML в сообщениях экранируется при выводе, а HTML-теги в новых сообщениях отклоняются.' => '免费输入字段接受纯文本。输出时消息中的 HTML 会被转义，并且新消息中的 HTML 标记会被拒绝。',
    'Галочка «Использовать CAPTCHA» включает Google reCAPTCHA v2 с проверкой «Я не робот» для выбранной формы.' => '“使用验证码”复选框启用 Google reCAPTCHA v2，对所选表单进行“我不是机器人”检查。',
    'Введите ключ сайта и секретный ключ для домена.' => '输入域的站点密钥和秘密密钥。',
    'Секрет хранится в защищённом файле настроек и используется только для серверной проверки. [Документация по серверной проверке](https://developers.google.com/recaptcha/docs/verify).' => '该秘密存储在受保护的设置文件中，仅用于服务器验证。 [服务器验证文档](https://developers.google.com/recaptcha/docs/verify)。',
    'Формы отправляются через AJAX.' => '表单通过 AJAX 提交。',
    'Заявки сохраняются в разделе «Сообщения».' => '申请保存在“消息”部分。',
    'Если указан получатель, для уведомлений используется `mail()`, которому нужна настроенная почта на хостинге.' => '如果指定了收件人，则 `mail()` 用于通知，这需要在主机上配置邮件。',
    'В разделе «Антиспам» можно редактировать списки слов, выражений, IPv4- и IPv6-адресов.' => '在反垃圾邮件部分，您可以编辑单词、表达式、IPv4 和 IPv6 地址的列表。',
    'Ссылки блокируются на сервере.' => '链接在服务器上被阻止。',
    'Адрес отправителя берётся из `REMOTE_ADDR`.' => '发件人地址取自 `REMOTE_ADDR`。',
    'За обратным прокси настройте восстановление исходного IP в веб-сервере для доверенных прокси.' => '在反向代理后面，为可信代理配置Web服务器中原始IP的恢复。',
    'Для каждой формы есть «Почтовый шаблон» с полями «Кому», «Копии (Cc)», «Тема письма» и «Текст письма».' => '每个表单都有一个“邮件模板”，其中包含“收件人”、“抄送（抄送）”、“电子邮件主题”和“电子邮件正文”字段。',
    'Адреса указываются через запятую.' => '地址用逗号分隔。',
    'Копии отправляются, если указан хотя бы один основной получатель.' => '如果至少指定了一个主要收件人，则会发送副本。',
    'Ключи полей вставляются в тему и текст в фигурных скобках, например `Привет {name}!`.' => '字段键插入到大括号中的主题和文本中，例如 `Привет {name}!`。',
    'Пустое значение поля подставляется как пустая строка, неизвестный ключ остаётся в письме.' => '空字段值被替换为空字符串，未知密钥保留在字母中。',
    'При пустой теме или тексте используется соответствующая часть стандартного письма.' => '如果主题或正文为空，则使用标准信件的相应部分。',
    'Вставьте `[callback]` или `[callback=Вызвать мастера]` в HTML страницы.' => '将 `[callback]` 或 `[callback=Вызвать мастера]` 插入 HTML 页面。',
    'Кнопка откроет форму с телефоном.' => '该按钮将打开一个包含电话号码的表单。',
    'Запросы сохраняются в разделе «Обратные звонки».' => '请求保存在“回调”部分。',
    'Там же задаются подписи кнопок и режим передачи заявки в телефонию.' => '按钮的签名以及将请求传输到电话的模式也在那里设置。',
    'По умолчанию выбран провайдер «Нет», и заявки только сохраняются.' => '默认情况下，选择“无”提供商并仅保存请求。',
    'Телефонию можно включить для ручной отправки из списка или для отправки сразу после приёма номера.' => '可以启用电话从列表中手动发送或在收到号码后立即发送。',
    '**Zadarma.** Задайте номер, SIP или добавочный оператора в админке, а ключи передайте PHP через `SITE_ZADARMA_KEY` и `SITE_ZADARMA_SECRET`. [Документация Zadarma API](https://zadarma.com/en/support/api/)' => '**Zadarma.** 在管理面板中设置号码、SIP 或操作员分机，并通过 `SITE_ZADARMA_KEY` 和 `SITE_ZADARMA_SECRET` 将密钥传输到 PHP。 [Zadarma API](https://zadarma.com/en/support/api/) 文档',
    '**HTTP API.** Задайте `SITE_CALLBACK_WEBHOOK_URL` с HTTPS-адресом и при необходимости `SITE_CALLBACK_WEBHOOK_TOKEN`.' => '**HTTP API。** 使用 HTTPS 地址指定 `SITE_CALLBACK_WEBHOOK_URL`，也可以选择指定 `SITE_CALLBACK_WEBHOOK_TOKEN`。',
    'Сайт отправляет POST с JSON-полями `id`, `phone`, `host`, `page`, `requested_at` и заголовком `Idempotency-Key`.' => '该站点发送包含 JSON 字段 `id`、`phone`、`host`、`page`、`requested_at` 和标头 `Idempotency-Key` 的 POST。',
    'Токен передаётся как Bearer.' => '令牌作为 Bearer 进行转移。',
    'Код ответа 2xx переводит заявку в статус «Принята телефонией».' => '响应代码 2xx 将请求转移到“电话已接受”状态。',
    'Добавьте процессу PHP право записи в `admin/callbacks/`.' => '授予 PHP 进程写入权限给 `admin/callbacks/`。',
    'Заявки используют настройки антиспама форм.' => '应用程序使用表单反垃圾邮件设置。',
    'Повтор на тот же номер ограничен одной минутой, по IP принимается до трёх заявок за 15 минут.' => '重复同一号码的时间限制为一分钟；每 15 分钟最多接受 3 个通过 IP 的请求。',
    'Инфоблоки и закрытая папка данных' => '信息块和封闭数据文件夹',
    'В разделе «Инфоблоки» можно создавать наборы данных, редактировать и перетаскивать строки.' => '在“信息块”部分中，您可以创建数据集、编辑和拖动行。',
    'В имени инфоблока и ключах столбцов разрешены `A–Z`, `a–z`, `0–9`, дефис и подчёркивание.' => '信息块名称和列键中允许使用 `A–Z`、`a–z`、`0–9`、连字符和下划线。',
    'Имена и ключи вводятся без пробелов.' => '输入的名称和密钥不带空格。',
    'Названия столбцов и значения ячеек можно писать по-русски.' => '列名和单元格值可以用俄语书写。',
    'Контролы соответствуют типам столбцов, а сохранение идёт через AJAX.' => '控件对应于列类型，并通过 AJAX 完成保存。',
    'Кнопка ☰ «Править как текст» переключает весь инфоблок на CSV с разделителем `|` и кнопкой копирования.' => '☰“编辑为文本”按钮将整个信息块切换为带有 `|` 分隔符和复制按钮的 CSV。',
    'Первые три строки содержат ключи, названия и типы столбцов.' => '前三行包含列的键、名称和类型。',
    'Затем идут строки данных.' => '然后是数据线。',
    'Дата в CSV имеет вид `ГГГГ-ММ-ДД`, «да/нет» хранится как `1` или `0`.' => 'CSV 中的日期为 `ГГГГ-ММ-ДД`，是/否存储为 `1` 或 `0`。',
    'Шаблон `phones` использует столбцы типа `tel` и текстовый столбец с названием.' => '`phones` 模板使用 `tel` 类型的列和带有标题的文本列。',
    'Свой шаблон можно разместить в `templates/local/iblock/имя.php`, где доступны `$block[\'columns\']` и `$block[\'rows\']`.' => '您可以将模板放置在 `templates/local/iblock/имя.php` 中，其中 `$block[\'columns\']` 和 `$block[\'rows\']` 可用。',
    'Путь `/data/myiblock.txt` внутри кода соответствует файлу `data/myiblock.txt.php`.' => '代码里面的路径`/data/myiblock.txt`对应的是文件`data/myiblock.txt.php`。',
    'Это текст UTF‑8 с PHP-заглушкой, которая возвращает 404 при прямом вызове. `router.php` закрывает всю папку при локальном запуске.' => '这是带有 PHP 存根的 UTF-8 文本，直接调用时会返回 404。 `router.php` 在本地运行时关闭整个文件夹。',
    'В `data/` есть правила для Apache и IIS.' => '`data/` 有针对 Apache 和 IIS 的规则。',
    'Для Apache разрешите применение `data/.htaccess`.' => '对于 Apache，启用 `data/.htaccess`。',
    'На Nginx настройте закрытие папки в конфигурации сайта, с учётом префикса при установке в подкаталог.' => '在 Nginx 上，在站点配置中配置要关闭的文件夹，并在子目录中安装时考虑前缀。',
    'После установки проверьте, что прямой запрос к `/data/` и файлу инфоблока получает 403 или 404.' => '安装后，检查对 `/data/` 的直接请求和信息块文件是否收到 403 或 404。',
    'Загрузка HTML-фрагментов' => '加载 HTML 片段',
    'Обычный адрес `/contacts/` открывает полную страницу.' => '通常的地址 `/contacts/` 打开整个页面。',
    'Запрос `?ajax=1` возвращает `<main>` с H1 и обработанным содержимым при наличии ключа сессии в заголовке `X-Site-Fragment`.' => '如果 `X-Site-Fragment` 标头中存在会话密钥，则请求 `?ajax=1` 将返回带有 H1 的 `<main>` 和已处理的内容。',
    'Фрагменты привязаны к текущему origin.' => '片段链接到当前原点。',
    'Страницы и фрагменты с ключами выдаются без кэширования.' => '带有键的页面和片段无需缓存即可提供。',
    'В JavaScript на странице сайта используйте встроенную функцию.' => '在网站页面上的 JavaScript 中，使用内置函数。',
    'При установке в подкаталог передавайте URL с префиксом сайта.' => '在子目录中安装时，传递带有站点前缀的 URL。',
    'Скрипт и стили берутся со страницы, которая вставляет фрагмент.' => '脚本和样式取自插入片段的页面。',
    'Публичные страницы остаются доступны по обычным адресам.' => '公共页面仍然可以通过常规地址访问。',
    'Шаблоны и ресурсы' => '模板和资源',
    'В «Настройки → Библиотеки и шрифты» по отдельности подключаются jQuery, Bootstrap, Font Awesome, Material UI, Alpine.js, htmx, Chart.js и GLightbox. Font Awesome хранится локально.' => '在“设置 → 库和字体”中，分别启用 jQuery、Bootstrap、Font Awesome、Material UI、Alpine.js、htmx、Chart.js 和 GLightbox。 Font Awesome 存储在本地。',
    'Остальные библиотеки загружаются браузером с CDN при включении. Material UI доступен в скриптах `type="module"` через `import { Button } from \'@mui/material\'`.' => '启用后，浏览器会从 CDN 下载其余库。 Material UI 可在脚本 `type="module"` 到 `import { Button } from \'@mui/material\'` 中使用。',
    'Для иконок подойдёт `[fa-icon=house]` или обычная разметка `<i class="fa-solid fa-house"></i>`.' => '对于图标，`[fa-icon=house]` 或常用标记 `<i class="fa-solid fa-house"></i>` 是合适的。',
    'Доступны 10 шрифтов Google с кириллицей.' => '提供 10 种带有西里尔字母的 Google 字体。',
    'Выбор заменяет системный шрифт сайта.' => '该选择将替换站点的系统字体。',
    'Значение «Системный» возвращает прежнее оформление.' => '值“System”返回先前的设计。',
    'В «Настройки → Тема и цвета → Сохранённые темы» есть пять готовых палитр со светлым и тёмным вариантами.' => '在“设置→主题和颜色→保存的主题”中有五个现成的调色板，带有浅色和深色选项。',
    '| Путь | Назначение |' => '|路径|目的地 |',
    '| `index.php` | Главная страница и общая точка входа |' => '| `index.php` |主页和一般入口点|',
    '| `contacts/index.php` | Пример страницы в отдельном каталоге |' => '| `contacts/index.php` |单独目录中的页面示例 |',
    '| `admin/` | Вход и редактор страниц |' => '| `admin/` |登录和页面编辑器 |',
    '| `app/site.php` | Чтение страниц, построение меню и название сайта в `SITE_NAME` |' => '| `app/site.php` |阅读 `SITE_NAME` 中的页面、构建菜单和网站标题 |',
    '| `templates/layout.php` | Общий макет, заголовок вкладки, метаданные и область контента |' => '| `templates/layout.php` |总体布局、选项卡标题、元数据和内容区域 |',
    '| `templates/header.php`, `menu.php`, `footer.php` | Шапка, меню и подвал |' => '| `templates/header.php`、`menu.php`、`footer.php` |页眉、菜单和页脚 |',
    '| `templates/css/`, `js/`, `icons/`, `images/` | Стили, скрипты, иконки и изображения |' => '| `templates/css/`、`js/`、`icons/`、`images/` |样式、脚本、图标和图像 |',
    '| `templates/components/`, `templates/iblock/` | Разметка компонентов и шаблоны инфоблоков |' => '| `templates/components/`、`templates/iblock/` |组件标记和信息块模板 |',
    '| `data/` | Файлы инфоблоков с защитой от прямого HTTP-доступа |' => '| `data/` |防止直接 HTTP 访问的信息块文件 |',
    'Движок собирает полную страницу из `[header]`, `[mobile-menu]`, `[menu]` и `[footer]`.' => '该引擎组装了 `[header]`、`[mobile-menu]`、`[menu]` 和 `[footer]` 的完整页面。',
    'Это верхняя панель, мобильное меню, правое меню и подвал.' => '它们是顶部栏、移动菜单、右侧菜单和页脚。',
    'Их можно переопределить одноимёнными подшаблонами в админке, включая отдельные варианты для поддоменов. PHP-переопределения шаблонов храните в `templates/local/` с тем же относительным путём, например `templates/local/footer.php`.' => '它们可以通过管理面板中的同名子模板重新定义，包括子域的单独选项。使用相同的相对路径将 PHP 模板覆盖存储在 `templates/local/` 中，例如 `templates/local/footer.php`。',
    'Обновление движка' => '引擎更新',
    'Полный архив нужен для новой установки.' => '新安装需要完整的存档。',
    'Для работающего сайта используйте `php-site-update.zip`.' => '对于实时站点，请使用 `php-site-update.zip`。',
    'В нём только движок и штатные шаблоны.' => '它仅包含引擎和标准模板。',
    'Сохранённые страницы, инфоблоки, настройки, пароли, сообщения и пользовательские расширения в архив не входят.' => '保存的页面、信息块、设置、密码、消息和用户扩展不包含在存档中。',
    'Нажмите «Обновить движок» в «Настройки → Обновления» или запустите ту же проверку из планировщика хостинга.' => '单击“设置→更新”中的“更新引擎”或从托管调度程序运行相同的检查。',
    'Источник по умолчанию — `bandaletov72/ewc-lite`.' => '默认源是 `bandaletov72/ewc-lite`。',
    'Для собственного репозитория задайте `SITE_GITHUB_REPO`.' => '对于您自己的存储库，将其设置为 `SITE_GITHUB_REPO`。',
    'В публичном репозитории токен не требуется.' => '公共存储库不需要令牌。',
    'Для закрытого репозитория передайте процессу PHP переменную `SITE_GITHUB_TOKEN` с правом чтения содержимого.' => '对于私有存储库，将变量 `SITE_GITHUB_TOKEN` 传递给具有内容读取权限的 PHP 进程。',
    'На сервере нужны PHP-расширения Zip и OpenSSL и возможность HTTPS-запросов к GitHub.' => '服务器需要 Zip 和 OpenSSL PHP 扩展以及向 GitHub 发出 HTTPS 请求的能力。',
    'Для ручной установки используйте ZIP.' => '对于手动安装，请使用 ZIP。',
    'На старой версии без `update.php` сначала распакуйте пакет поверх проекта, сохранив существующие `.htaccess` и файлы из `maintenance/`, если они есть.' => '在没有 `update.php` 的旧版本上，首先将包解压到项目顶部，保留现有的 `.htaccess` 和 `maintenance/` 中的文件（如果有）。',
    'Если вы правили штатные шаблоны, перенесите правки в `templates/local/` до обновления.' => '如果您编辑了标准模板，请在更新之前将编辑内容传输到 `templates/local/`。',
    'Установщик проверяет список и контрольные суммы файлов, а для GitHub также проверяет подпись доверенным открытым ключом `maintenance/release-public.pem`.' => '安装程序会验证文件的列表和校验和，对于 GitHub，它还会使用可信公钥 `maintenance/release-public.pem` 验证签名。',
    'Для следующего выпуска измените версию в `app/version.php` и соберите пакет через `php update.php --build php-site-update.zip`.' => '对于下一个版本，将版本更改为 `app/version.php` 并通过 `php update.php --build php-site-update.zip` 构建包。',
    'Подпишите ZIP своим закрытым RSA-ключом с SHA‑256, храните закрытый ключ отдельно от сайта.' => '使用 SHA-256 的 RSA 私钥对 ZIP 进行签名，并将私钥与站点分开存储。',
    'Затем разместите ZIP и `.sig` в GitHub Release с тегом `vX.Y.Z` или в `updates/vX.Y.Z/` и обновите `updates/latest.json` до `{"version":"X.Y.Z"}`.' => '然后将 ZIP 和 `.sig` 推送到带有标签 `vX.Y.Z` 的 GitHub Release 或 `updates/vX.Y.Z/` 并将 `updates/latest.json` 更新为 `{"version":"X.Y.Z"}`。',
    'Расширения' => '扩展',
    'Модули движка можно добавлять в `app/extensions/` вместе с обновлениями.' => '引擎模块可以随更新一起添加到 `app/extensions/`。',
    'Собственные модули храните в `extensions/`, вне пакета обновления. PHP-файл возвращает массив определений.' => '将您自己的模块存储在更新包之外的 `extensions/` 中。 PHP 文件返回定义数组。',
    'У одиночного компонента `kind` равен `single`, у компонента с аргументом — `wrapped`.' => '对于单个组件，`kind` 等于 `single`，对于带参数的组件，它等于 `wrapped`。',
    'Движок распознаёт новые коды на существующих страницах.' => '引擎识别现有页面上的新代码。',
    'Компонент может объявить меню параметров в `settings`, задав для каждого параметра `label`, `default` и массив `options`.' => '组件可以在 `settings` 中声明选项菜单，将每个选项设置为 `label`、`default` 和数组 `options`。',
    'Значения поступают в `$context[\'settings\']`.' => '这些值转到 `$context[\'settings\']`。',
    'Компонент из примера вставляется как `[notice]Важное сообщение[/notice]`.' => '示例组件作为 `[notice]Важное сообщение[/notice]` 插入。',
    'Для локального запуска выполните в каталоге проекта команду php -S 127.0.0.1:8000 router.php и откройте http://127.0.0.1:8000/admin/.' => '本地运行，在项目目录下运行命令 php -S 127.0.0.1:8000 router.php 并打开 http://127.0.0.1:8000/admin/.',
    'На хостинге сначала выполните php admin/setup.php, затем введите полученный одноразовый код на первом шаге мастера в /admin/.' => '在托管上，首先运行 php admin/setup.php，然后在 /admin/. 中输入向导第一步中收到的一次性代码',
    'Сначала создайте логин и пароль.' => '首先创建用户名和密码。',
    'На втором шаге задайте название сайта, метаописание по умолчанию, текст подвала, палитру и режим темы.' => '第二步，设置站点名称、默认元描述、页脚文本、调色板和主题模式。',
    'При наличии PHP GD можно сразу загрузить логотип и создать из него favicon.' => '如果您有 PHP GD，您可以立即下载徽标并从中创建网站图标。',
    'Второй шаг можно пропустить или продолжить при следующем входе.' => '您可以跳过第二步或下次登录时继续。',
    'Откройте «Страницы → Новая страница».' => '转到页面 → 新页面。',
    'Укажите адрес, например /Services-1/Repair/ или /Services-1/Price_2.php, заполните заголовок и сохраните.' => '输入地址，例如/Services-1/Repair/或/Services-1/Price_2.php，填写标题并保存。',
    'Для адреса папки движок сам создаст каталоги и index.php.' => '对于文件夹地址，引擎本身会创建目录和index.php。',
    'В именах разрешены A–Z, a–z, 0–9, дефис и подчёркивание.' => '名称中允许使用 A-Z、a-z、0-9、连字符和下划线。',
    'В корне зарезервирована главная страница, а создание страниц в служебных каталогах закрыто.' => '主页面保留在根目录下，服务目录下的页面创建是关闭的。',
    'Снятие галочки «В меню» убирает ссылку из штатных меню, сохраняя доступ по прямому адресу.' => '取消选中“在菜单中”框将从常规菜单中删除链接，同时保留对直接地址的访问。',
    'У страницы с адресом папки галочка также управляет пунктами вложенных страниц.' => '在具有文件夹地址的页面上，该复选框还控制子页面上的项目。',
    'Кнопка «Скрыть» убирает ссылку и закрывает публичный адрес страницы до повторной публикации.' => '“隐藏”按钮会删除链接并关闭页面的公共地址，直到再次发布。',
    'Нажмите «Сохранить» в редакторе.' => '在编辑器中单击“保存”。',
    'Затем воспользуйтесь ссылкой «Открыть страницу» или «Перейти».' => '然后使用“打开页面”或“前往”链接。',
    'Если ссылка исчезла, проверьте, опубликована ли страница.' => '如果链接消失，请检查页面是否已发布。',
    'Для изменений на поддомене сверяйте домен в адресной строке.' => '对于子域的更改，请检查地址栏中的域。',
    'Откройте «Настройки → Основные».' => '打开设置 → 常规。',
    'Поле «Текст подвала» поддерживает [year] для текущего года.' => '页脚文本字段支持当前年份的 [year]。',
    'В блоке «Логотипы и иконки сайта» можно загрузить изображения или нажать «Создать favicon из логотипа».' => '在“徽标和站点图标”块中，您可以上传图像或单击“从徽标创建网站图标”。',
    'Загрузка и преобразование требуют PHP GD.' => '加载和转换需要PHP GD。',
    'В «Настройки → Тема и цвета» выберите режим и палитру.' => '在设置 → 主题和颜色中，选择模式和调色板。',
    'Сохраните текущую палитру в списке, чтобы её можно было применить позже.' => '将当前调色板保存在列表中，以便稍后使用。',
    'Кнопка «Использовать по умолчанию» запоминает палитру для команды «Вернуть тему по умолчанию».' => '“用作默认值”按钮会记住“将主题恢复为默认值”命令的调色板。',
    'Шрифт меняется в разделе «Библиотеки и шрифты».' => '可以在“库和字体”部分更改字体。',
    'Названия и образцы в списке показаны соответствующими шрифтами.' => '列表中的名称和示例以适当的字体显示。',
    'Значение «Системный» возвращает обычный шрифт.' => '值“System”返回正常字体。',
    'Общие блоки header, mobile-menu, menu и footer редактируются во вкладке «Шаблоны оформления».' => '公共块标题、移动菜单、菜单和页脚在“设计模板”选项卡中编辑。',
    'Там же «Служебные заголовки» вставляют HTML в head или перед закрывающим тегом body.' => '在同一位置，“服务标头”将 HTML 插入到 head 中或结束 body 标记之前。',
    'Для обычных CSS и JavaScript есть отдельная вкладка «CSS и JS».' => '对于常规 CSS 和 JavaScript，有一个单独的“CSS 和 JS”选项卡。',
    'Код одной страницы добавляется в её редакторе.' => '一页的代码将添加到其编辑器中。',
    'Добавьте поддомен в разделе «Домены».' => '在“域”部分添加子域。',
    'Затем задайте отдельное значение подшаблона в разделе «Подшаблоны», выбрав нужный домен.' => '然后通过选择所需的域在“子模板”部分中设置单独的子模板值。',
    'Шапку и другие блоки меняйте кнопкой «Шаблоны» рядом с доменом.' => '使用域旁边的“模板”按钮更改标题和其他块。',
    'Доменная версия имеет приоритет перед общей. DNS и веб-сервер должны направлять поддомен в каталог этого сайта.' => '域版本优先于通用版本。 DNS 和 Web 服务器必须将子域指向该站点的目录。',
    'Откройте «Настройки → Контакты и соцсети».' => '打开“设置→联系人和社交网络”。',
    'Заполните адреса, подписи и телефоны.' => '填写地址、签名和电话号码。',
    'Код [soc-icons] выводит иконки всех настроенных сетей.' => '代码 [soc-icons] 显示所有已配置网络的图标。',
    'Для отдельной ссылки используйте, например, [tg] или [vk].' => '对于单个链接，请使用 [tg] 或 [vk] 等。',
    'Откройте «Формы», настройте поля, обязательность, максимальную длину и текст кнопки.' => '打开表单，配置字段、必填字段、最大长度和按钮文本。',
    'Сохраните форму и вставьте её код, например [form1], в HTML страницы.' => '保存表单并将其代码（例如 [form1]）粘贴到页面的 HTML 中。',
    'Откройте «Сообщения».' => '打开消息。',
    'Заявки сохраняются там после успешной отправки формы.' => '成功提交表格后，申请将保存在那里。',
    'Для уведомлений проверьте адреса в поле «Кому» в почтовом шаблоне формы и работу функции mail() на хостинге.' => '对于通知，请检查表单邮件模板中“收件人”字段中的地址以及主机上 mail() 功能的功能。',
    'Откройте нужную форму и найдите блок «Почтовый шаблон».' => '打开所需的表单并找到“邮件模板”块。',
    'Укажите адреса в полях «Кому» и «Копии (Cc)» через запятую.' => '在“收件人”和“副本（抄送）”字段中输入地址，以逗号分隔。',
    'В теме и тексте используйте ключи полей в фигурных скобках, например Привет {name}!' => '在主题和正文中，使用大括号中的字段键，例如 Hello {name}！',
    'Кнопки под текстом вставляют выбранную переменную.' => '文本下方的按钮插入选定的变量。',
    'Пустые тема или текст используют стандартное уведомление.' => '空白主题或文本使用标准通知。',
    'Проверьте обязательные поля, длину, формат телефона и email.' => '检查必填字段、长度、电话和电子邮件格式。',
    'В полях свободного ввода используются обычный текст без HTML и адресов сайтов.' => '免费输入字段使用纯文本，不含 HTML 或网站地址。',
    'Списки запрещённых слов и IP находятся в разделе «Антиспам».' => '禁止词语和 IP 列表位于反垃圾邮件部分。',
    'Галочка «Использовать CAPTCHA» требует ключ сайта и секретный ключ Google reCAPTCHA v2 для нужного домена.' => '“使用验证码”复选框需要所需域的站点密钥和 Google reCAPTCHA v2 密钥。',
    'В разделе «Обратные звонки».' => '在“回调”部分。',
    'Компонент добавляется в страницу кодом [callback] или [callback=Вызвать мастера].' => '该组件将添加到页面，代码为 [callback] 或 [callback=Вызвать мастера]。',
    'При провайдере «Нет» заявки сохраняются в админке.' => '如果选择“否”提供商，应用程序将保存在管理面板中。',
    'При настроенной телефонии доступна ручная или автоматическая передача.' => '配置电话后，可以使用手动或自动传输。',
    'В разделе «Инфоблоки» нажмите «Новый инфоблок», настройте столбцы и добавьте строки.' => '在“信息块”部分中，单击“新建信息块”，配置列并添加行。',
    'В имени инфоблока и ключах столбцов используйте A–Z, a–z, 0–9, дефис или подчёркивание без пробелов.' => '在信息块名称和列键中，使用 A–Z、a–z、0–9、连字符或下划线，不带空格。',
    'Сохраните и скопируйте код вставки из редактора инфоблока.' => '保存并复制信息块编辑器中的嵌入代码。',
    'Для списка телефонов используйте шаблон phones.' => '如需电话列表，请使用电话模板。',
    'Откройте инфоблок и нажмите «Править как текст».' => '打开信息块并单击“编辑为文本”。',
    'В CSV используется разделитель |.' => 'CSV 使用 |分隔符。',
    'Дальше идут данные.' => '接下来是数据。',
    'Заключайте поле с разделителем, кавычкой или переносом строки в двойные кавычки и удваивайте внутренние кавычки.' => '将带有分隔符、引号或换行符的字段括在双引号和双内引号中。',
    'Сверьте путь в коде компонента с папкой на сервере.' => '检查组件代码中的路径与服务器上的文件夹。',
    'Например, [fotos]/images/myfotos/[/fotos] использует фотографии в images/myfotos/ или templates/images/myfotos/.' => '例如，[fotos]/images/myfotos/[/fotos] 使用 images/myfotos/ 或 templates/images/myfotos/. 中的照片',
    'Для [files] проверьте расширение файла.' => '对于 [files]，检查文件扩展名。',
    'Список поддерживаемых расширений и параметры есть в справке по компонентам.' => '可以在组件帮助中找到支持的扩展和参数的列表。',
    'Фрагмент страницы требует действующего публичного сеанса и токена на том же сайте.' => '页面片段需要同一站点上的有效公共会话和令牌。',
    'Для подгрузки внутри сайта используйте window.siteFetchContent(), которая передаёт токен.' => '要在站点内部加载，请使用 window.siteFetchContent()，它会传输令牌。',
    'Для обычного перехода открывайте адрес страницы без параметра ajax.' => '对于正常的转换，打开不带ajax参数的页面地址。',
    'В «Настройки → Обновления» сравните установленную версию с последней версией из GitHub, затем нажмите «Обновить движок».' => '在“设置”→“更新”中，将安装的版本与 GitHub 中的最新版本进行比较，然后单击“更新引擎”。',
    'Если GitHub недоступен, админка показывает версию, которую удалось проверить в прошлый раз.' => '如果 GitHub 不可用，管理面板将显示上次检查的版本。',
    'Для ручного обновления передайте архив php-site-update.zip команде php update.php.' => '要手动更新，请将 php-site-update.zip 存档传递给 php 命令 update.php。',
    'Пакет обновления заменяет файлы движка и штатные шаблоны.' => '更新包替换了引擎文件和标准模板。',
    'Свои PHP-шаблоны храните в templates/local/.' => '将您的 PHP 模板存储在 templates/local/. 中',
    'Сделайте копию всего каталога сайта вместе со скрытыми файлами.' => '复制整个站点目录以及隐藏文件。',
    'Страницы находятся в корне и их каталогах, инфоблоки в data/, файлы настроек и учётной записи в admin/.' => '页面位于根及其目录，data/中的信息块，admin/.中的设置和帐户文件',
    'Сохраните также свои шаблоны, загруженные изображения, сообщения и заявки.' => '还可以保存您的模板、上传的图像、消息和应用程序。',
    'В копию входят секреты настроек, поэтому храните её вне публичного каталога.' => '该副本包含配置机密，因此请将其保存在公共目录之外。',
    'Сначала прочитайте сообщение рядом с формой.' => '首先阅读表格旁边的消息。',
    'При конфликте изменений скопируйте свои правки и откройте редактор заново.' => '如果更改发生冲突，请复制您的编辑内容并再次打开编辑器。',
    'При ошибке записи попросите хостинг проверить права записи процесса PHP в нужную папку и файл admin/write-lock.php.' => '如果出现写入错误，请要求您的主机检查所需文件夹和文件 admin/write-lock.php. 中 PHP 进程的写入权限',
    'При ошибке обновления проверьте доступ сервера к GitHub и наличие PHP Zip и OpenSSL.' => '如果更新失败，请检查服务器对 GitHub 的访问以及 PHP Zip 和 OpenSSL 的可用性。',
    'Шаблоны и компоненты' => '模板和组件',
    'Полная страница подключает эти блоки автоматически.' => '整页自动连接这些块。',
    'Общие версии редактируются в «Шаблоны оформления», а для отдельного домена — в разделе «Домены».' => '通用版本在“设计模板”中编辑，对于单个域，则在“域”部分中编辑。',
    'Вставляет содержимое опубликованной страницы.' => '插入已发布页面的内容。',
    'Максимальная вложенность — десять уровней.' => '最大嵌套为十层。',
    'Повтор страницы в одной цепочке пропускается.' => '跳过同一链中重复的页面。',
    'Галочка «Показывать в меню» добавляет ссылку в штатные меню.' => '“在菜单中显示”复选框添加到标准菜单的链接。',
    'При пустом названии берётся заголовок.' => '如果名称为空，则使用标题。',
    'Если отключить галочку у страницы папки, её вложенные страницы тоже исчезнут из меню.' => '如果取消选中文件夹页面的复选框，其子页面也将从菜单中消失。',
    'Общий код редактируется во вкладке «CSS и JS».' => '通用代码在“CSS和JS”选项卡中编辑。',
    'Код страницы редактируется в блоке «CSS и JavaScript страницы» и подключается после общего.' => '页面代码在“CSS 和 JavaScript 页面”块中编辑，并包含在常规页面之后。',
    'В поля вставьте содержимое CSS и JavaScript.' => '将 CSS 和 JavaScript 内容粘贴到字段中。',
    'Подключён Font Awesome Free 7.3.1.' => 'Font Awesome Free 7.3.1 已连接。',
    'Короткий код работает в контенте и HTML блоков оформления.' => '简短的代码适用于内容和 HTML 设计块。',
    'Доступны стили solid, regular и brands.' => '有纯色、常规和品牌款式可供选择。',
    'Добавьте рядом с иконкой текст, если она обозначает действие.' => '如果图标代表操作，则在图标旁边添加文本。',
    'Подключения управляются в «Настройки → Библиотеки и шрифты».' => '连接在“设置→库和字体”中管理。',
    'Для Material UI используйте модульный JavaScript.' => '对于 Material UI，请使用模块化 JavaScript。',
    'Выбранный шрифт Google заменяет системный шрифт сайта.' => '所选的 Google 字体将替换网站的系统字体。',
    'Добавьте записи в «Настройки → Основные».' => '将条目添加到“设置→常规”。',
    'Вставляйте ключ в текст, заголовок, название сайта или подвал.' => '将密钥插入文本、页眉、站点标题或页脚中。',
    'В разделе «Подшаблоны» задайте имя, описание и значение.' => '在子模板部分中，指定名称、描述和值。',
    'Для домена сначала берётся его значение, затем общее.' => '对于域，首先取其值，然后取其一般值。',
    'Подшаблон может содержать HTML.' => '子模板可以包含 HTML。',
    'В заголовках разметка убирается.' => '标头中的标记已被删除。',
    'Код [author] выводит Eurowebcart CMS Lite, имя автора Бандалетов Павел и ссылку на GitHub.' => '代码 [author] 输出 Eurowebcart CMS Lite、作者姓名 Бандалетов Павел 以及 GitHub 的链接。',
    'В стандартном подвале подпись появляется автоматически.' => '在标准页脚中，签名会自动出现。',
    'В собственный HTML подвала вставьте код в нужное место.' => '在您自己的 HTML 页脚中，将代码粘贴到您想要的位置。',
    'Код [page-content] вставляет текст главной в шаблон [home].' => '代码 [page-content] 将正文插入模板 [home] 中。',
    'В «Страницах» откройте /privacy/, чтобы изменить текст политики.' => '在 Pages 中，转至 /privacy/ 编辑策略文本。',
    'Подстановки [site-name] и [site-url] берутся из основных настроек.' => '替换 [site-name] 和 [site-url] 取自主设置。',
    'В разделе «Шаблоны оформления → Функции» отредактируйте functions.php.' => '在“设计模板→功能”部分中，编辑functions.php。',
    'В PHP-коде translit() или ew_call() вызывает зарегистрированную функцию.' => '在 PHP 代码中，translit() 或 ew_call() 调用已注册的函数。',
    'Короткий код [func=translit] доступен в содержимом и в поле «Свой HTML».' => '短代码 [func=translit] 可在内容和“自定义 HTML”字段中找到。',
    'Выводит поддерживаемые файлы. icons, size и download принимают on или off, order — asc или desc.' => '列出支持的文件。图标、大小和下载接受打开或关闭、顺序 - 升序或降序。',
    'Разрешены zip, pdf, xls, xlsx, doc, docx, png, gif, jpg, jpeg, mp4, mov и mp3.' => '允许使用 Zip、pdf、xls、xlsx、doc、docx、png、gif、jpg、jpeg、mp4、mov 和 mp3。',
    'В разделе «Формы» настройте поля, их максимальную длину, текст кнопки и получателя. «Использовать CAPTCHA» включает виджет Google reCAPTCHA v2 с проверкой ответа на сервере.' => '在“表单”部分中，配置字段、最大长度、按钮文本和收件人。 “使用验证码”启用 Google reCAPTCHA v2 小部件，并在服务器上进行响应验证。',
    'Заявки отправляются через AJAX и видны в разделе «Сообщения».' => '请求通过 AJAX 发送，并在“消息”部分中可见。',
    'Тема и текст хранятся отдельно для каждой формы.' => '每个表单的主题和文本分别存储。',
    'В почтовом шаблоне вставляйте ключи полей в фигурных скобках.' => '在您的电子邮件模板中，在花括号中插入字段键。',
    'Списки получателей и копий разделяются запятыми.' => '收件人列表和副本列表以逗号分隔。',
    'Открывает форму с телефоном.' => '打开包含电话号码的表单。',
    'Заявка сохраняется в разделе «Обратные звонки».' => '该应用程序保存在“回调”部分。',
    'Подпись кнопки можно задать в коде.' => '按钮标签可以在代码中设置。',
    'С провайдером «Нет» отправка в телефонию выключена.' => '对于“否”提供商，将禁用发送到电话。',
    'Создайте набор данных в разделе «Инфоблоки».' => '在“Infoblocks”部分创建一个数据集。',
    'В имени инфоблока и ключах столбцов разрешены A–Z, a–z, 0–9, дефис и подчёркивание.' => '信息块名称和列键中允许使用 A–Z、a–z、0–9、连字符和下划线。',
    'Пробелы запрещены.' => '不允许有空格。',
    'Шаблон table показывает таблицу, phones выводит телефонные столбцы со ссылками для звонка.' => '表格模板显示表格，电话显示带有呼叫链接的电话列。',
    'Поддерживаются закрывающие коды [iblock] и [/iblock].' => '支持关闭代码 [iblock] 和 [/iblock]。',
    'Каждый код выводит ссылку своей соцсети.' => '每个代码都会显示其社交网络的链接。',
    'Адреса и подписи задаются в «Настройки → Контакты и соцсети».' => '地址和签名在“设置→联系人和社交网络”中设置。',
    'Язык админки' => '后台语言',
    'Скрытый тег' => '隐藏标签',
    'Фильтр по тегам' => '按标签筛选',
    'ВСЕ' => '全部',
    'Тип «Скрытый тег» добавляет фильтры над таблицей. В ячейке укажите один или несколько тегов через запятую. Кнопка «ВСЕ» показывает все строки.' => '「隐藏标签」类型会在表格上方添加筛选按钮。在单元格中输入一个或多个用逗号分隔的标签。「全部」显示所有行。',
    'Кнопка вызова формы' => '表单按钮',
    'Заказать' => '下单',
    'Тип «Кнопка вызова формы» добавляет в строку таблицы кнопку «Заказать». Выберите форму по названию в выпадающем списке. В CSV укажите код формы, например form86.' => '表单按钮列会在已配置的行中显示「下单」按钮。从下拉列表中选择表单名称。在 CSV 中填写表单代码，例如 form86。',
];
